import { acceptPresentationEvent, canOpenPresentationRoute, parsePresentationCommand } from "./wayne-presentation.mjs";
import { parseLiveAvatarEvent, transcriptEventKey } from "./liveavatar-events.mjs";
const app=document.querySelector("#app");
const state={token:sessionStorage.getItem("ix-token")||"",data:null,route:location.hash.slice(1)||"dashboard",search:"",wayneOpen:false,dialog:null,projectView:"table",settingsTab:"profile",reportPeriod:"all",tenderFilters:{search:"",category:"",relevance:""},presentationFilters:{},presentation:{active:false,route:null,context:null,fullscreenPending:false}};
let avatarRuntime={room:null,session:null,timeout:null,countdown:null,listening:false,cameraStream:null,connecting:false,ending:false,stopPromise:null,sessionType:"sandbox",launchPayload:null,logicalMeetingId:null,savedEvents:new Set(),commandEvents:new Set(),emailDrafts:[],pendingEventSaves:new Set(),transcriptPinned:true,transcriptTimer:null,userTranscriptSeen:false};
const waynePrefs={microphone:false,camera:false,panelOpen:true,panelTab:"agenda",notes:"",meetingId:null,followUpId:null,presentationContext:null};
const nav=[
  ["dashboard","home","Dashboard"],["crm","users","CRM"],["projects","folder","Projects"],["team","tasks","Team & Tasks"],
  ["quotations","invoice","Quotations & Invoices"],["tenders","briefcase","Tenders"],["funding","coins","Funding"],["finance","chart","Finance"],
  ["compliance","shield","Compliance"],["documents","document","Documents"],["meetings","calendar","AI Meetings"],["reports","report","Reports"],["settings","settings","Settings"]
];
const money=cents=>new Intl.NumberFormat("en-ZA",{style:"currency",currency:"ZAR",maximumFractionDigits:0}).format(Number(cents||0)/100).replace("ZAR","R");
const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt=value=>value?new Date(value).toLocaleDateString("en-ZA",{day:"2-digit",month:"short",year:"numeric"}):"—";
const api=async(path,options={})=>{if(path==="/api/avatar/session"&&options.method==="POST"&&avatarRuntime.launchPayload)options={...options,body:JSON.stringify(avatarRuntime.launchPayload)};const response=await fetch(path,{...options,headers:{Authorization:`Bearer ${state.token}`,...(options.body?{"Content-Type":"application/json"}:{}),...(options.headers||{})}});const result=await response.json().catch(()=>({error:`HTTP ${response.status}`}));if(!response.ok){const error=new Error(result.error||"Request failed");error.payload=result;error.status=response.status;throw error}return result};
const icon=(name,tone="")=>{const aliases={"▤":"document","▱":"folder","△":"shield","▥":"coins","♙":"users","⌕":"search"};return`<span class="round-icon ${tone}">${uiIcon(aliases[name]||name)}</span>`};
const uiIcon=(name)=>{const paths={home:"<path d='M3 11 12 4l9 7'/><path d='M5 10v10h14V10M9 20v-6h6v6'/>",users:"<circle cx='9' cy='8' r='3'/><path d='M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5v1'/>",folder:"<path d='M3 6h7l2 2h9v11H3z'/>",tasks:"<path d='m4 7 2 2 4-4M12 7h8M4 14l2 2 4-4M12 14h8'/>",invoice:"<path d='M6 3h12v18l-3-2-3 2-3-2-3 2zM9 8h6M9 12h6M9 16h3'/>",briefcase:"<rect x='3' y='7' width='18' height='12' rx='2'/><path d='M8 7V4h8v3M3 12h18M10 12v2h4v-2'/>",coins:"<ellipse cx='12' cy='6' rx='7' ry='3'/><path d='M5 6v5c0 1.7 3.1 3 7 3s7-1.3 7-3V6M5 11v5c0 1.7 3.1 3 7 3s7-1.3 7-3v-5'/>",chart:"<path d='M4 20V10M10 20V4M16 20v-7M22 20H2'/>",shield:"<path d='M12 3 20 6v6c0 5-3.4 8-8 10-4.6-2-8-5-8-10V6z'/><path d='m8 12 3 3 5-6'/>",document:"<path d='M6 3h8l4 4v14H6zM14 3v5h5M9 13h6M9 17h6'/>",calendar:"<rect x='3' y='5' width='18' height='16' rx='2'/><path d='M7 3v4M17 3v4M3 10h18M8 15h2M14 15h2'/>",report:"<path d='M4 20h16M6 17v-4M11 17V7M16 17v-7M21 17V4'/>",settings:"<circle cx='12' cy='12' r='3'/><path d='M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H3v-4h.2a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1 2.8-2.8.1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.6V3h4v.2a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L20 7.2l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4h-.2a1.7 1.7 0 0 0-1.8.8z'/>",search:"<circle cx='11' cy='11' r='7'/><path d='m20 20-4-4'/>",bell:"<path d='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4'/>",menu:"<path d='M4 7h16M4 12h16M4 17h16'/>",close:"<path d='m5 5 14 14M19 5 5 19'/>",arrow:"<path d='M5 12h14M14 7l5 5-5 5'/>"};return`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.document}</svg>`};

function loginGlyph(name){const path=name==="users"?"<path d='M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2'/><circle cx='9' cy='7' r='4'/><path d='M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75'/>":name==="lock"?"<rect x='5' y='10' width='14' height='11' rx='2'/><path d='M8 10V7a4 4 0 0 1 8 0v3'/>":"<path d='M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z'/><circle cx='12' cy='12' r='3'/>";return`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`}
function login(){return`<main class="login login-page"><section class="login-panel"><div class="login-inner"><div class="login-brand"><div class="login-logo"><span class="login-brand-x">X</span><span class="login-brand-word"><b>INFINITE-<i>X</i></b><small>GROUP</small></span></div><span class="login-brand-divider"></span><strong>OS</strong><em>WORKSPACE</em></div><div class="login-motto">MANAGE <b>·</b> BUILD <b>·</b> GROW <b>·</b> TOGETHER</div><div class="login-copy"><h1>Sign in to your<br><span>workspace</span></h1><p class="platform-positioning">AI-powered project and business management.</p><p class="login-support">Bring projects, people, tenders, finance, funding and follow-through into one accountable workspace.</p></div><form id="login-form" class="login-form"><label for="account">Select account</label><div class="select-wrap"><span class="login-field-icon account-icon">${loginGlyph("users")}</span><select id="account" name="userId" required><option value="director">Alex Mokoena — Director</option><option value="tm">Thandi Maseko — Project Manager</option><option value="sc">Sipho Cele — Electrician</option><option value="mr">Mpho Radebe — Finance</option></select></div><label for="password">Password</label><div class="password-wrap"><span class="login-field-icon">${loginGlyph("lock")}</span><input id="password" name="password" type="password" placeholder="Enter demo password" required autocomplete="current-password"><button type="button" id="show-password" aria-label="Show password">${loginGlyph("eye")}</button></div><div class="login-access"><span>DEMO MODE</span><p><b>Fictional, isolated operational data with live public tender records.</b> Use the review password supplied with the project. No real credentials are shown here.</p></div><p class="form-error" id="login-error" role="alert"></p><button class="sign-in" type="submit"><span>Sign in</span><b>→</b></button></form><small class="login-footnote">Role-based permissions remain active after sign-in. Real Mode starts empty except for public tender records.</small></div></section><aside class="login-visual" aria-label="INFINITE-X Group reception and brand environment"></aside></main>`}
function brand(){return`<div class="brand"><strong>X</strong><span><b>INFINITE-<i>X</i></b><small>GROUP</small></span></div><em>OS</em>`}
function sidebar(){return`<aside class="sidebar" id="sidebar" aria-label="Primary navigation"><div class="mobile-brand">${brand()}<button class="sidebar-close" id="sidebar-close" aria-label="Close navigation">${uiIcon("close")}</button></div><nav>${nav.map(([key,ico,label])=>`<a href="#${key}" data-route="${key}" class="${state.route===key?"active":""}"><span>${uiIcon(ico)}</span><b>${label}</b></a>`).join("")}</nav><button class="wayne-shortcut" data-wayne><div class="wayne-portrait"><span>W</span><i></i></div><b>Meet Wayne</b><small>Start a conversation</small></button><div class="help"><span class="help-icon">?</span><span><b>Need help?</b><small>Access guides and support.</small></span></div></aside>`}
function topbar(){const d=state.data,modeHelp=d.mode==="DEMO"?"Demo Mode uses isolated fictional operational data and live public tender records. Switch to Real Mode.":"Real Mode uses isolated operational data and live public tender records. Switch to Demo Mode.";return`<header class="topbar"><button class="menu-toggle" id="menu-toggle" aria-label="Open navigation" aria-controls="sidebar" aria-expanded="false">${uiIcon("menu")}</button><div class="top-brand">${brand()}<button class="mode-badge" id="mode-switch" aria-label="${modeHelp}" title="${modeHelp}">${d.mode} MODE</button></div><div class="search">${uiIcon("search")}<input id="global-search" placeholder="Search projects, tenders, clients, documents…" value="${esc(state.search)}"><div class="search-results" id="search-results"></div></div><div class="profile"><button class="bell" aria-label="Notifications">${uiIcon("bell")}<i></i></button><span>${esc((d.user.preferredName||d.user.name)[0])}</span><b>${esc(d.user.role)}</b><button id="logout" aria-label="Sign out">⌄</button></div></header>`}
function kpi(route,label,value,help,ico,tone){return`<a href="#${route}" data-route="${route}" class="kpi">${icon(ico,tone)}<div><span>${label}</span><strong>${value}</strong><small>${help}</small></div><b>→</b></a>`}
function status(value){const cls=/block|risk|overdue|missing|error|not ready|unavailable|attention/i.test(value)?"danger":/progress|provided|reported|preview/i.test(value)?"warn":"good";return`<span class="status ${cls}">${esc(value)}</span>`}
function progress(value){return`<span class="progress"><i style="width:${Math.max(0,Math.min(100,Number(value||0)))}%"></i></span>`}
function panel(title,action,body,cls=""){return`<section class="panel ${cls}"><header><h2>${title}</h2>${action||""}</header>${body}</section>`}
function dashboard(){const d=state.data,m=d.metrics,next=d.meetings.find(meeting=>meeting.status==="Scheduled"&&new Date(meeting.starts_at)>new Date()),fund=d.funding[0],rank={High:0,Medium:1,Low:2,Review:3},prioritisedTenders=[...d.tenders].sort((a,b)=>(rank[a.relevance_label]??4)-(rank[b.relevance_label]??4)||String(a.close_date).localeCompare(String(b.close_date))),attentionTender=prioritisedTenders.find(t=>!t.readiness.submissionReady),tenderAttention=attentionTender?(attentionTender.readiness.mandatory===0?{tone:"red",ico:"▤",title:"Tender requirements not yet assessed",sub:`${attentionTender.reference} · ${attentionTender.relevance_label||"Review"} relevance`,route:"tenders",label:"Review tender"}:{tone:"red",ico:"▤",title:`${attentionTender.readiness.missing+attentionTender.readiness.unverified} tender items need verification`,sub:`${attentionTender.reference} · mandatory requirements`,route:"tenders",label:"Review tender"}):null,attention=[...(tenderAttention?[tenderAttention]:[]),...d.projects.filter(p=>p.blocker).slice(0,1).map(p=>({tone:"amber",ico:"▥",title:p.blocker,sub:`${p.name} · recorded project blocker`,route:"projects",label:"View project"})),...(m.overdueInvoiceBalance?[{tone:"red",ico:"⌕",title:`${money(m.overdueInvoiceBalance)} in invoices is overdue`,sub:m.overdueThirtyDayCount?`${m.overdueThirtyDayCount} invoice${m.overdueThirtyDayCount===1?"":"s"} more than 30 days overdue`:`${m.overdueInvoiceCount} overdue invoice${m.overdueInvoiceCount===1?"":"s"}`,route:"finance",label:"View invoices"}]:[])];
return`<div class="dashboard"><div class="heading"><div><h1>Business overview</h1><p>Projects, people and priorities in one place.</p></div><div class="date-pill">▣ <span>${new Date().toLocaleDateString("en-ZA",{weekday:"short",day:"2-digit",month:"short",year:"numeric"})}</span></div></div>
<div class="kpis">${kpi("tenders","Active tenders",m.activeTenders,`${m.highRelevanceTenders} high relevance · all sectors`,"▤","green")}${kpi("projects","Active projects",m.activeProjects,"In delivery","▱","blue")}${kpi("team","Overdue tasks",m.overdueTasks,"Require attention","△","red")}${kpi("finance","Outstanding invoices",money(m.outstandingInvoices),`${d.invoices.filter(i=>i.balanceCents>0).length} unpaid invoices`,"▤","green")}${kpi("funding","Funding needed",money(m.fundingNeeded),`Across ${d.funding.length} application${d.funding.length===1?"":"s"}`,"▥","purple")}${kpi("meetings","Open meeting actions",m.openMeetingActions,"From recorded meetings","♙","orange")}</div>
<div class="brief-row">${panel("Wayne's business briefing",``, `<p class="panel-sub">Hello, ${esc(d.user.preferredName)}. Here is what needs your attention.</p><div class="brief-list">${attention.map(x=>`<a href="#${x.route}" data-route="${x.route}">${icon(x.ico,x.tone)}<span><b>${esc(x.title)}</b><small>${esc(x.sub)}</small></span><u>${x.label}</u><em>›</em></a>`).join("")}</div><div class="brief-actions"><button class="primary" data-wayne>▢ <b>Talk to Wayne</b> →</button><button data-route="reports">▤ <b>View records</b> →</button></div>`,"wayne-brief")}
${panel("Next business review","",next?`<div class="review-time"><b>${new Date(next.starts_at).toLocaleDateString("en-ZA",{weekday:"short",day:"2-digit",month:"short"})} · ${new Date(next.starts_at).toLocaleTimeString("en-ZA",{hour:"2-digit",minute:"2-digit",timeZone:"Africa/Johannesburg"})} SAST</b></div><ul class="review-list"><li>✉ <span>Agenda email: ${next.agenda_send_at?new Date(next.agenda_send_at).toLocaleString("en-ZA",{weekday:"long",hour:"2-digit",minute:"2-digit",timeZone:"Africa/Johannesburg"}):"With reminder"}</span></li><li>♧ <span>Reminder: ${next.reminder_minutes} minutes before</span></li><li>☑ <span>${m.openMeetingActions} previous actions to follow up</span></li></ul><button class="outline full" data-route="meetings">▣ <b>Review agenda</b> →</button>`:`<div class="empty">No review scheduled.</div><button class="outline full" data-new-meeting>Schedule review</button>`,"review")}</div>
<div class="middle-row">${panel("Active projects",`<button data-route="projects">View all projects →</button>`,`<div class="table projects-table"><div class="tr th"><span>Project</span><span>Client</span><span>Owner</span><span>Progress</span><span>Status</span><span>Due date</span></div>${d.projects.slice(0,3).map(p=>`<button class="tr" data-route="projects"><b>${esc(p.name)}</b><span>${esc(p.client)}</span><span class="avatar">${p.owner.split(" ").map(x=>x[0]).join("")}</span><span>${p.progress}% ${progress(p.progress)}</span><span>${status(p.status)}</span><span>${fmt(p.due_date)} ⋮</span></button>`).join("")}</div>`,"projects")}
${panel("Funding readiness",`<button data-route="funding">View all funding →</button>`,fund?`<div class="fund-card"><div>${icon("▥","olive")}<span><small>${fund.type}</small><strong>${money(fund.gapCents)}</strong><em>${fund.status}</em></span></div><button data-route="funding" class="fund-alert">△ <b>${fund.documents.filter(x=>x.status!=="Verified").length} documents outstanding</b> ›</button></div><button class="outline full" data-route="funding">▤ <b>View application</b> →</button>`:`<div class="empty">No funding records in ${d.mode.toLowerCase()} mode.</div>`,"funding")}</div>
<div class="lower-row">${panel("Latest team updates",`<button data-route="team">View all updates →</button>`,`<div class="table updates-table"><div class="tr th"><span>Date</span><span>Team member</span><span>Update</span><span>Evidence</span><span>Status</span></div>${d.updates.slice(0,3).map(u=>`<button class="tr" data-route="team"><span>${new Date(u.created_at).toLocaleString("en-ZA",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}</span><span><i class="avatar">${u.author.split(" ").map(x=>x[0]).join("")}</i></span><span>${esc(u.status==="Blocked"?u.blocker:`${u.title} updated.`)}</span><u>${esc(u.evidence||"—")}</u><span>${status(u.status==="Reported complete"?"On track":u.status)}</span></button>`).join("")}</div>`,"updates")}
${panel("Tender readiness",`<span class="panel-tools"><span>${m.highRelevanceTenders} high relevance</span><button data-route="tenders">View all tenders →</button></span>`,`<div class="table tender-table"><div class="tr th"><span>Tender</span><span>Category</span><span>Close date</span><span>Readiness</span></div>${prioritisedTenders.slice(0,2).map(t=>`<button class="tr" data-tender-detail="${esc(t.id)}"><b>${esc(t.reference)}<small>${esc(t.title)}</small></b><span>${esc(t.category)}</span><span>${fmt(t.close_date)}</span><span>${status(t.readiness.mandatory===0?"Not assessed":t.readiness.submissionReady?`Ready (${t.readiness.score}%)`:`In progress (${t.readiness.score}%)`)} ⋮</span></button>`).join("")}</div>`,"tenders")}</div></div>`}

function pageHeader(title,copy,actions=""){return`<div class="page-head"><div><h1>${title}</h1><p>${copy}</p></div>${actions}</div>`}
function legacyProjectsPage(){const d=state.data;return`${pageHeader("Projects","Milestones, tasks, owners, dependencies, blockers and completion evidence.",moduleTools("New project","data-new-project","Search projects…",`<select data-list-status><option value="">All statuses</option><option>Planned</option><option>On track</option><option>At risk</option><option>Completed</option></select>`))}<div class="record-grid module-list">${d.projects.map(p=>`<article class="record-card filter-item" data-search="${esc(`${p.name} ${p.client} ${p.owner}`.toLowerCase())}" data-status="${p.status}"><header><div><small>${esc(p.client)}</small><h2>${esc(p.name)}</h2></div>${status(p.status)}</header><div class="big-progress"><b>${p.progress}%</b>${progress(p.progress)}</div><dl><div><dt>Owner</dt><dd>${esc(p.owner)}</dd></div><div><dt>Due</dt><dd>${fmt(p.due_date)}</dd></div><div><dt>Budget</dt><dd>${money(p.budget_cents)}</dd></div><div><dt>Recorded costs</dt><dd>${money(p.cost_cents)}</dd></div></dl>${p.blocker?`<p class="callout danger">Recorded blocker: ${esc(p.blocker)}</p>`:""}<ul class="checklist">${d.milestones.filter(m=>m.project_id===p.id).map(m=>`<li><span>◆</span><b>${esc(m.title)}</b><small>${fmt(m.due_date)} · ${esc(m.status)}</small></li>`).join("")||"<li>No milestones recorded.</li>"}</ul><div class="button-row"><button data-edit-project="${p.id}">Edit</button><button data-new-milestone="${p.id}">Milestone</button><button data-route="team">Tasks & evidence</button></div></article>`).join("")||empty("No projects","Create the first active-mode project.")}</div>`}
function tasksPage(){const d=state.data,taskNames=new Map(d.tasks.map(task=>[task.id,task.title]));return`${pageHeader("Team & Tasks","Employees report progress and evidence; managers verify completion separately.",moduleTools("Assign task","data-new-task","Search tasks or owners…",`<button data-new-user>Add employee</button>`))}<div class="team-strip">${d.users.map(u=>`<article><span class="avatar">${u.name.split(" ").map(x=>x[0]).join("")}</span><b>${esc(u.name)}</b><small>${esc(u.role)} · ${u.active?"Active":"Inactive"}</small>${d.permissions.director&&u.id!==d.user.id?`<button data-toggle-user="${u.id}">${u.active?"Deactivate":"Activate"}</button>`:""}</article>`).join("")}</div><div class="wide-table module-list"><div class="row head"><span>Task / Project</span><span>Owner</span><span>Due</span><span>Status</span><span>Evidence</span><span></span></div>${d.tasks.map(t=>`<div class="row filter-item" data-search="${esc(`${t.title} ${t.project} ${t.assignee}`.toLowerCase())}"><span><b>${esc(t.title)}</b><small>${esc(t.project)}${t.dependency_id?` · depends on ${esc(taskNames.get(t.dependency_id)||"another task")}`:""}</small></span><span>${esc(t.assignee)}</span><span>${fmt(t.due_date)}</span><span>${status(t.status)}</span><span>${esc(t.evidence||"None")}</span><button data-task="${t.id}">Update</button></div>`).join("")||empty("No tasks","Create a project, then assign its first task.")}</div><h2 class="section-title">Update history</h2><div class="activity-list">${d.updates.map(u=>`<div><span>${status(u.status)}</span><p><b>${esc(u.author)}</b> updated ${esc(u.title)}<small>${fmt(u.created_at)} · ${esc(u.evidence||u.blocker||"No evidence reference")}</small></p></div>`).join("")||empty("No updates","Employee updates will appear here.")}</div>`}
function legacyTendersPage(){const d=state.data,categories=[...new Set(d.tenders.map(t=>t.category))];return`${pageHeader("Tender readiness","Discover, import and track every category. Readiness counts only verified mandatory requirements.",moduleTools("Import tender","data-new-tender","Search tender, reference or organisation…",`<select data-list-category><option value="">All categories</option>${categories.map(x=>`<option>${esc(x)}</option>`).join("")}</select><button id="refresh-tenders">Refresh official source</button>`))}<div class="connector">${d.connectors.map(c=>`<div><b>${esc(c.name)}</b><span>${status(c.status)}</span><small>Last refresh: ${fmt(c.last_refresh)} · <a href="${c.source_url}" target="_blank">Official source ↗</a>${c.error?` · ${esc(c.error)}`:""}</small></div>`).join("")}</div><div class="record-grid module-list">${d.tenders.map(t=>`<article class="record-card filter-item" data-search="${esc(`${t.reference} ${t.title} ${t.organisation}`.toLowerCase())}" data-category="${esc(t.category)}"><header><div><small>${esc(t.reference)} · ${esc(t.category)}</small><h2>${esc(t.title)}</h2></div>${status(t.readiness.submissionReady?"Submission ready":"Not ready")}</header><p>${esc(t.organisation)} · closes ${fmt(t.close_date)}${t.briefing_date?` · briefing ${fmt(t.briefing_date)}`:""}</p><div class="readiness"><strong>${t.readiness.score}%</strong>${progress(t.readiness.score)}<small>${t.readiness.verified}/${t.readiness.mandatory} mandatory items verified</small></div><ul class="checklist">${t.requirements.map(r=>`<li><button data-requirement="${r.id}" title="Advance requirement status">${r.status==="Verified"?"✓":r.status==="Provided"?"◷":"×"}</button><b>${esc(r.label)}</b><small>${esc(r.status)}${r.document_ref?` · ${esc(r.document_ref)}`:""}</small></li>`).join("")||"<li>No requirements recorded; readiness is 0%.</li>"}</ul><p class="basis">${esc(t.readiness.basis)}</p><div class="button-row"><button data-new-requirement="${t.id}">Add requirement</button><a class="outline button-link" href="${esc(t.source_url)}" target="_blank" rel="noreferrer">Open source ↗</a></div></article>`).join("")||empty("No tenders","Import a tender or refresh the official connector in Real Mode.")}</div>`}
function legacyFundingPage(){const d=state.data;return`${pageHeader("Funding","Recorded needs and document readiness. No offers, eligibility or approvals are inferred.",moduleTools("New funding need","data-new-funding","Search funding records…"))}<div class="record-grid module-list">${d.funding.map(f=>`<article class="record-card filter-item" data-search="${esc(`${f.type} ${f.purpose} ${f.provider} ${f.po_reference}`.toLowerCase())}"><header><div><small>${esc(f.type)} · ${esc(f.po_reference||"No PO")}</small><h2>${esc(f.purpose)}</h2></div>${status(f.status)}</header><dl><div><dt>Required costs</dt><dd>${money(f.requiredCents)}</dd></div><div><dt>Confirmed funds</dt><dd>${money(f.availableCents)}</dd></div><div><dt>Funding gap</dt><dd class="lime">${money(f.gapCents)}</dd></div><div><dt>Provider</dt><dd>${esc(f.provider||"Not selected")}</dd></div></dl><ul class="checklist">${f.documents.map(x=>`<li><button data-funding-doc="${x.id}" title="Toggle verification">${x.status==="Verified"?"✓":"×"}</button><b>${esc(x.label)}</b><small>${esc(x.status)}</small></li>`).join("")}</ul><button data-new-funding-doc="${f.id}">Add required document</button><p class="basis">${esc(f.assumption)}</p></article>`).join("")||empty("No funding records","Create the first recorded funding need.")}</div>`}
function financePage(){const d=state.data;return`${pageHeader("Financial visibility","Receipts, revenue, expenses and receivables remain distinct.",moduleTools("Record expense","data-new-expense","Search invoices…"))}<div class="mini-kpis"><article><small>Issued revenue</small><b>${money(d.metrics.revenue)}</b></article><article><small>Recorded receipts</small><b>${money(d.metrics.receipts)}</b></article><article><small>Recorded expenses</small><b>${money(d.metrics.expenses)}</b></article><article><small>Receivables</small><b>${money(d.metrics.outstandingInvoices)}</b></article></div><div class="wide-table module-list"><div class="row head"><span>Invoice</span><span>Client</span><span>Total</span><span>Paid</span><span>Balance</span><span>Action</span></div>${d.invoices.map(i=>`<div class="row filter-item" data-search="${esc(`${i.number} ${i.client}`.toLowerCase())}"><span><b>${esc(i.number)}</b><small>${i.project_id||"General"} · due ${fmt(i.due_date)}</small></span><span>${esc(i.client)}</span><span>${money(i.total_cents)}</span><span>${money(i.paidCents)}</span><span>${money(i.balanceCents)}</span><span>${i.balanceCents?`<button data-payment="${i.id}">Record payment</button>`:status("Paid")}</span></div>`).join("")||empty("No financial records","Issue an invoice by converting a quotation.")}</div><h2 class="section-title">Recorded expenses</h2><div class="activity-list">${d.expenses.map(e=>`<div><span>${money(e.amount_cents)}</span><p><b>${esc(e.description)}</b><small>${esc(e.project_id||"General operations")} · ${fmt(e.incurred_at)}</small></p></div>`).join("")||empty("No expenses","Record an expense to include it in financial summaries.")}</div>`}
function meetingsPage(){const d=state.data,history=d.wayneMeetings||[];return`${pageHeader("Meetings & follow-through","Schedule reviews, preserve recorded Wayne discussions and track approved actions.",`<button class="primary" data-new-meeting>Schedule meeting</button>`)}<section class="wayne-history-register"><header><div><h2>Wayne meeting history</h2><p>Search recorded meetings in Africa/Johannesburg time. Scheduled calendar entries are not treated as conversations.</p></div><div class="history-filters"><input type="search" data-wayne-history-search placeholder="Search title or recap"><input type="date" data-wayne-history-date></div></header><div class="wayne-history-list">${history.map(m=>`<article class="wayne-history-item" data-history-search="${esc(`${m.title} ${m.recap} ${m.unresolved_topics}`.toLowerCase())}" data-history-date="${esc(new Intl.DateTimeFormat("en-CA",{timeZone:"Africa/Johannesburg",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date(m.started_at)))}"><header><span><small>${esc(new Date(m.started_at).toLocaleString("en-ZA",{timeZone:"Africa/Johannesburg",dateStyle:"medium",timeStyle:"short"}))} SAST</small><h3>${esc(m.title)}</h3></span>${status(m.transcript_completeness)}</header><p><b>Recap:</b> ${esc(m.recap||"No recap is available.")}</p><p><b>Unresolved:</b> ${esc(m.unresolved_topics||"None recorded")}</p><details><summary>Transcript (${m.transcript.length} events)</summary>${m.transcript.length?m.transcript.map(event=>`<p><b>${event.speaker==="assistant"?"Wayne":"You"}:</b> ${esc(event.content)} <small>${esc(new Date(event.occurred_at).toLocaleString("en-ZA",{timeZone:"Africa/Johannesburg"}))}</small></p>`).join(""):`<p>This meeting exists, but its transcript is unavailable.</p>`}</details><details><summary>Linked approved actions</summary>${m.approvedActions.length?`<ul>${m.approvedActions.map(action=>`<li>${esc(action.title)} · ${esc(action.status||"Open")}</li>`).join("")}</ul>`:"<p>No approved action was recorded.</p>"}</details><button class="outline" data-history-recall="${esc(m.id)}">Recall in a new Wayne meeting</button></article>`).join("")||empty("No recorded Wayne meetings","Start a Wayne meeting to create an authorised history record.")}</div><p class="empty history-no-results" hidden>I couldn’t find a recorded meeting on that date.</p></section><div class="meeting-grid"><section>${d.meetings.map(m=>`<article class="meeting-card"><header><div><small>${fmt(m.starts_at)} · ${new Date(m.starts_at).toLocaleTimeString("en-ZA",{hour:"2-digit",minute:"2-digit",timeZone:"Africa/Johannesburg"})} SAST</small><h2>${esc(m.topic)}</h2></div>${status(m.status)}</header><pre>${esc(m.agenda)}</pre>${m.summary?`<div class="minutes"><b>Confirmed summary</b><p>${esc(m.summary)}</p><b>Decisions</b><p>${esc(m.decisions||"None recorded")}</p></div>`:""}<div class="button-row">${m.status==="Scheduled"?`<button data-reschedule="${m.id}">Reschedule</button><button data-minutes="${m.id}">Record minutes</button><button class="danger-btn" data-cancel="${m.id}">Cancel</button>`:""}</div></article>`).join("")||empty("No scheduled meetings","Schedule a review to create persistent notification jobs.")}</section><aside>${panel("Notification jobs","",`<ul class="simple-list">${d.notifications.map(n=>`<li><span><b>${esc(n.kind)}</b><small>${new Date(n.scheduled_for).toLocaleString("en-ZA")} · attempts ${n.attempts}</small></span>${status(n.status)}</li>`).join("")||"<li>No jobs.</li>"}</ul>`)}${panel("Preview outbox","",`<ul class="simple-list">${d.outbox.map(o=>`<li><span><b>${esc(o.subject)}</b><small>${esc(o.recipient)} · ${fmt(o.created_at)}</small></span>${status(o.status)}</li>`).join("")||"<li>No preview messages.</li>"}</ul>`)}${panel("Approved actions","",`<ul class="simple-list">${d.actions.map(a=>`<li><span><b>${esc(a.title)}</b><small>${esc(a.owner)} · ${fmt(a.due_date)}</small></span>${a.status!=="Completed"?`<button data-complete-action="${a.id}">Complete</button>`:status(a.status)}</li>`).join("")||"<li>No actions.</li>"}</ul>`)}</aside></div>`}
function legacySettingsPage(){const d=state.data;return`${pageHeader("Settings","Profile, company, permissions, mode separation and integration status.")}<div class="settings-grid"><form class="record-card" id="profile-form"><h2>My Profile</h2><label>Preferred name<input name="preferredName" value="${esc(d.user.preferredName)}" required></label><label>Pronunciation guidance<input name="pronunciation" value="${esc(d.user.pronunciation||"")}" placeholder="Optional"></label><button class="primary">Save profile</button></form><form class="record-card" id="company-form"><h2>Company settings · ${d.mode} Mode</h2><label>Company name<input name="companyName" value="${esc(d.settings?.company_name||"")}" required></label><label>Email<input name="email" type="email" value="${esc(d.settings?.email||"")}"></label><label>Phone<input name="phone" value="${esc(d.settings?.phone||"")}"></label><button class="primary" ${d.permissions.director?"":"disabled"}>Save company</button></form><article class="record-card"><h2>Permissions</h2><p>Signed in as <b>${esc(d.user.role)}</b>.</p><ul class="simple-list">${d.users.map(u=>`<li><span><b>${esc(u.name)}</b><small>${esc(u.role)}</small></span>${status(u.active?"Active":"Inactive")}</li>`).join("")}</ul></article><article class="record-card"><h2>Runtime status</h2><dl><div><dt>Business records</dt><dd>${esc(d.runtime.database)}</dd></div><div><dt>OpenEdge verification</dt><dd>${d.runtime.openedgeVerified?"ABL sidecar schema and calculations verified":"Verification failed"}</dd></div><div><dt>Live PAS repository</dt><dd>${d.runtime.openedgeActive?"Active":"Not active — REST mapping/cutover pending"}</dd></div><div><dt>Wayne AI</dt><dd>${d.runtime.aiConfigured?"Configured":"Unavailable — OPENAI_API_KEY missing"}</dd></div><div><dt>LiveAvatar Wayne</dt><dd>${d.runtime.avatarConfigured?"Configured":`Unavailable — sandbox/business-tool support not verified; ${d.runtime.avatarLimitSeconds}s direction retained`}</dd></div><div><dt>Email</dt><dd>${esc(d.runtime.emailMode)} outbox; no delivery claim</dd></div><div><dt>Timezone</dt><dd>${esc(d.runtime.timezone)}</dd></div></dl><p class="callout warn">Demo and Real records, documents, conversations, meetings and jobs are mode-scoped server-side. PAS is not claimed active while the operational repository remains SQLite.</p></article></div>`}
function moduleTools(createLabel,createAttr,placeholder="Search records…",options=""){return`<div class="module-tools"><input data-list-search placeholder="${placeholder}" aria-label="${placeholder}">${options}<button class="primary" ${createAttr}>${createLabel}</button></div>`}
function legacyCrmPage(){const d=state.data;return`${pageHeader("CRM","Manage clients and open their connected projects, quotations and invoices.",moduleTools("New client","data-new-client","Search clients…",`<select data-list-status><option value="">All statuses</option><option>Active</option><option>Archived</option></select>`))}<div class="record-grid module-list">${d.clients.map(c=>{const projects=d.projects.filter(p=>p.client===c.name).length,quotes=d.quotations.filter(q=>q.client_id===c.id).length,invoices=d.invoices.filter(i=>i.client===c.name).length;return`<article class="record-card filter-item" data-search="${esc(`${c.name} ${c.contact_name} ${c.email}`.toLowerCase())}" data-status="${c.status}"><header><div><small>${esc(c.contact_name||"No contact recorded")}</small><h2>${esc(c.name)}</h2></div>${status(c.status)}</header><p>${esc(c.email||"No email")} · ${esc(c.phone||"No phone")}</p><dl><div><dt>Projects</dt><dd>${projects}</dd></div><div><dt>Quotations</dt><dd>${quotes}</dd></div><div><dt>Invoices</dt><dd>${invoices}</dd></div><div><dt>Updated</dt><dd>${fmt(c.updated_at)}</dd></div></dl><p class="basis">${esc(c.notes||"No notes recorded.")}</p><div class="button-row"><button data-edit-client="${c.id}">Edit</button><button data-route="projects">Projects</button><button data-route="quotations">Financial records</button>${c.status!=="Archived"?`<button class="danger-btn" data-archive-client="${c.id}">Archive</button>`:""}</div></article>`}).join("")||empty("No clients","Create the first active-mode client.")}</div>`}
function legacyQuotationsPage(){const d=state.data;return`${pageHeader("Quotations & Invoices","Create priced quotations, convert accepted work, preview records and post protected payments.",moduleTools("New quotation","data-new-quote","Search number, client or description…"))}<div class="record-grid module-list">${d.quotations.map(q=>`<article class="record-card filter-item" data-search="${esc(`${q.number} ${q.client} ${q.description}`.toLowerCase())}"><header><div><small>${esc(q.number)} · valid to ${fmt(q.valid_until)}</small><h2>${esc(q.client||"Unlinked client")}</h2></div>${status(q.status)}</header><p>${esc(q.description)}</p><dl><div><dt>Subtotal</dt><dd>${money(q.subtotal_cents)}</dd></div><div><dt>VAT 15%</dt><dd>${money(q.vat_cents)}</dd></div><div><dt>Total</dt><dd>${money(q.total_cents)}</dd></div><div><dt>Project</dt><dd>${esc(q.project_id||"General")}</dd></div></dl><div class="button-row"><button data-preview-record="quotation:${q.id}">Preview</button>${!q.invoice_id?`<button class="primary" data-convert-quote="${q.id}">Convert to invoice</button>`:`<span class="basis">Invoice ${esc(q.invoice_id)}</span>`}</div></article>`).join("")||empty("No quotations","Create a quotation for an active client.")}</div><h2 class="section-title">Invoices & balances</h2><div class="wide-table module-list"><div class="row head"><span>Invoice</span><span>Client</span><span>Total</span><span>Paid</span><span>Balance</span><span>Action</span></div>${d.invoices.map(i=>`<div class="row filter-item" data-search="${esc(`${i.number} ${i.client}`.toLowerCase())}"><span><b>${esc(i.number)}</b><small>${fmt(i.due_date)}</small></span><span>${esc(i.client)}</span><span>${money(i.total_cents)}</span><span>${money(i.paidCents)}</span><span>${money(i.balanceCents)}</span><span><button data-preview-record="invoice:${i.id}">Preview</button>${i.balanceCents?` <button data-payment="${i.id}">Payment</button>`:""}</span></div>`).join("")}</div>`}
function legacyCompliancePage(){const d=state.data;return`${pageHeader("Compliance","Track applicable requirements, ownership, evidence and expiry without inferring compliance.",moduleTools("New requirement","data-new-compliance","Search requirements…",`<select data-list-status><option value="">All statuses</option><option>Compliant</option><option>Expiring soon</option><option>Evidence required</option></select>`))}<div class="record-grid module-list">${d.compliance.map(c=>`<article class="record-card filter-item" data-search="${esc(`${c.title} ${c.standard_ref} ${c.owner}`.toLowerCase())}" data-status="${c.status}"><header><div><small>${esc(c.standard_ref||"Internal requirement")}</small><h2>${esc(c.title)}</h2></div>${status(c.status)}</header><dl><div><dt>Owner</dt><dd>${esc(c.owner)}</dd></div><div><dt>Expiry</dt><dd>${fmt(c.expiry_date)}</dd></div><div><dt>Linked record</dt><dd>${esc(c.related_type||"Company")} ${esc(c.related_id||"")}</dd></div><div><dt>Evidence</dt><dd>${esc(c.evidence||"Missing")}</dd></div></dl><button data-edit-compliance="${c.id}" class="outline full">Update requirement</button></article>`).join("")||empty("No compliance requirements","Create an applicable requirement.")}</div>`}
function legacyDocumentsPage(){const d=state.data;return`${pageHeader("Documents","Upload, revise, preview, download and archive active-mode evidence.",moduleTools("Upload document","data-new-document","Search title, file or link…",`<select data-list-status><option value="">All statuses</option><option>Current</option><option>Superseded</option><option>Archived</option></select>`))}<div class="wide-table module-list"><div class="row head"><span>Document</span><span>Link</span><span>Revision</span><span>Uploaded by</span><span>Status</span><span>Actions</span></div>${d.documents.map(x=>`<div class="row filter-item" data-search="${esc(`${x.title} ${x.file_name} ${x.related_type} ${x.related_id}`.toLowerCase())}" data-status="${x.status}"><span><b>${esc(x.title)}</b><small>${esc(x.file_name)} · ${fmt(x.created_at)}</small></span><span>${esc(x.related_type)} · ${esc(x.related_id||"General")}</span><span>Rev ${x.revision}</span><span>${esc(x.uploader)}</span><span>${status(x.status)}</span><span><a class="small-button" href="/api/documents/${x.id}/download?preview=1" target="_blank" data-auth-link>Preview</a> <a class="small-button" href="/api/documents/${x.id}/download" data-auth-link>Download</a>${x.status!=="Archived"?` <button data-archive-document="${x.id}">Archive</button>`:""}</span></div>`).join("")||empty("No documents","Upload an active-mode document.")}</div><p class="basis">Uploads are limited to 1 MB in this local build. Revision numbers advance when the same document title is uploaded again.</p>`}
const reportPeriodOptions={all:"All recorded data","30":"Last 30 days","90":"Last 90 days",year:"Current calendar year"};
function reportDateInPeriod(value,period){if(period==="all")return true;if(!value)return false;const date=new Date(value);if(Number.isNaN(date.getTime()))return false;const now=new Date();if(period==="year")return date.getFullYear()===now.getFullYear();const days=Number(period);return date>=new Date(now.getTime()-days*86400000)}
function reportsPage(){
  const d=state.data,period=state.reportPeriod in reportPeriodOptions?state.reportPeriod:"all",periodLabel=reportPeriodOptions[period];
  const projects=d.projects.filter(item=>reportDateInPeriod(item.updated_at,period));
  const tenders=d.tenders.filter(item=>reportDateInPeriod(item.published_date||item.last_refreshed,period));
  const invoices=(d.invoices||[]).filter(item=>reportDateInPeriod(item.due_date,period));
  const payments=(d.payments||[]).filter(item=>item.status==="Recorded"&&reportDateInPeriod(item.recorded_at,period));
  const expenses=(d.expenses||[]).filter(item=>reportDateInPeriod(item.incurred_at,period));
  const tenderGroups=[...tenders.reduce((groups,item)=>groups.set(item.status||"Unspecified",(groups.get(item.status||"Unspecified")||0)+1),new Map())].sort((a,b)=>b[1]-a[1]);
  const colours=["#b3ff00","#25c8ff","#7c4cff","#ffad00","#00d989","#ff6478"],tenderTotal=tenders.length;
  let cursor=0;const donutStops=tenderGroups.map(([name,count],index)=>{const start=cursor,end=cursor+(count/Math.max(1,tenderTotal))*100;cursor=end;return`${colours[index%colours.length]} ${start}% ${end}%`}).join(",");
  const financeAllowed=Boolean(d.permissions?.finance),financeRecords=invoices.length+payments.length+expenses.length;
  const financeValues=[["Total invoiced",invoices.reduce((sum,item)=>sum+Number(item.total_cents||0),0),"Invoice totals selected by recorded due date"],["Recorded receipts",payments.reduce((sum,item)=>sum+Number(item.amount_cents||0),0),"Payments with Recorded status selected by recorded timestamp"],["Recorded expenses",expenses.reduce((sum,item)=>sum+Number(item.amount_cents||0),0),"Expenses selected by incurred date"]];
  const financeMax=Math.max(...financeValues.map(item=>item[1]),1),filter=`<div class="report-filter"><label for="report-period">Reporting period</label><select id="report-period">${Object.entries(reportPeriodOptions).map(([value,label])=>`<option value="${value}" ${period===value?"selected":""}>${label}</option>`).join("")}</select><small>Mode: ${esc(d.mode)} · Values use authorised active-mode records only.</small></div>`;
  const projectChart=projects.length?`<div class="project-bars" role="img" aria-label="Project completion percentages for ${esc(periodLabel)}">${projects.map(project=>`<div class="project-bar" aria-label="${esc(project.name)}: ${Number(project.progress)} percent complete"><span title="${esc(project.name)}">${esc(project.name)}</span><div><i style="width:${Math.max(0,Math.min(100,Number(project.progress||0)))}%"></i></div><b>${Number(project.progress)}%</b></div>`).join("")}</div>`:`<div class="chart-empty"><b>No project updates in this period</b><span>Choose a broader period to include projects by their recorded update date.</span></div>`;
  const tenderChart=tenderTotal?`<div class="donut-layout"><div class="donut" role="img" aria-label="${tenderGroups.map(([name,count])=>`${name}: ${count}`).join(", ")}" style="background:conic-gradient(${donutStops})"><span><b>${tenderTotal}</b><small>tracked</small></span></div><div class="chart-legend">${tenderGroups.map(([name,count],index)=>`<div><i style="background:${colours[index%colours.length]}"></i><span>${esc(name)}</span><b>${count}</b></div>`).join("")}</div></div>`:`<div class="chart-empty"><b>No tracked tenders in this period</b><span>Choose a broader period to include tenders by published or refresh date.</span></div>`;
  const financeChart=!financeAllowed?`<div class="chart-empty"><b>Finance report unavailable</b><span>Your role does not permit access to financial records.</span></div>`:financeRecords?`<div class="finance-bars" role="img" aria-label="Financial record totals for ${esc(periodLabel)}. ${financeValues.map(item=>`${item[0]} ${money(item[1])}`).join(", ")}">${financeValues.map(([label,value,basis])=>`<div class="finance-bar" data-cents="${value}" aria-label="${label}: ${money(value)}. ${basis}"><b>${esc(label)}</b><div><i style="height:${Math.max(value?8:0,(value/financeMax)*100)}%"></i></div><strong>${money(value)}</strong></div>`).join("")}</div>`:`<div class="chart-empty"><b>No financial records in this period</b><span>No invoice due dates, recorded receipts or incurred expenses match the selected period.</span></div>`;
  return`${pageHeader("Reports","Authorised operational evidence calculated from the active workspace.",filter)}<div class="mini-kpis"><article><small>Project delivery</small><b>${projects.length} projects</b><span>${d.tasks.filter(t=>t.status==="Blocked").length} blocked tasks in the active workspace</span></article><article><small>Tender pipeline</small><b>${tenders.length} tracked</b><span>${tenders.filter(t=>t.readiness.submissionReady).length} recorded submission ready</span></article><article><small>Receivables</small><b>${financeAllowed?money(d.metrics.outstandingInvoices):"Restricted"}</b><span>${financeAllowed?`${d.invoices.filter(i=>i.balanceCents).length} open invoices`:"Not available for this role"}</span></article><article><small>Funding gap</small><b>${financeAllowed?money(d.metrics.fundingNeeded):"Restricted"}</b><span>${financeAllowed?"Recorded needs only":"Not available for this role"}</span></article></div><div class="report-charts"><article class="report-chart"><header><div><h2>Project completion</h2><p>${esc(periodLabel)} · progress recorded against projects updated in the period</p></div></header>${projectChart}</article><article class="report-chart"><header><div><h2>Tracked tenders by status</h2><p>${esc(periodLabel)} · current status of tenders published or refreshed in the period</p></div></header>${tenderChart}</article><article class="report-chart finance-chart"><header><div><h2>Financial activity</h2><p>${esc(periodLabel)} · invoiced, receipts and expenses are distinct record categories—not cash balance or profit</p></div></header>${financeChart}<small class="chart-basis">Invoice selection uses due date; receipts use recorded timestamp; expenses use incurred date.</small></article></div><div class="report-grid"><article class="record-card"><h2>Operations report</h2><p>Project ownership, progress, deadlines and recorded blockers.</p><a class="primary button-link" href="/api/reports/operations.csv?period=${period}" data-auth-link>Export filtered CSV</a></article><article class="record-card"><h2>Finance report</h2><p>Issued totals, recorded payments and deterministic balances.</p><a class="primary button-link" href="/api/reports/finance.csv?period=${period}" data-auth-link>Export filtered CSV</a></article><article class="record-card"><h2>Tender readiness</h2><p>Mandatory requirement verification and submission-ready flags.</p><a class="primary button-link" href="/api/reports/tenders.csv?period=${period}" data-auth-link>Export filtered CSV</a></article></div><div class="wide-table report-activity"><div class="row head"><span>Recent activity</span><span>Author</span><span>Record</span><span>Date</span></div>${d.auditLog.filter(item=>reportDateInPeriod(item.created_at,period)).slice(0,12).map(a=>`<div class="row"><span>${esc(a.action)}</span><span>${esc(a.author||a.user_id)}</span><span>${esc(a.record_type||"—")} ${esc(a.record_id||"")}</span><span>${fmt(a.created_at)}</span></div>`).join("")||`<div class="empty"><b>No activity in this period</b><span>Choose a broader reporting period.</span></div>`}</div>`
}

/* Restored operational register patterns from the original OS. These overrides keep
   the clone's service-backed workflows while replacing the simplified card walls. */
function moduleFrame(title,copy,actions,body){return`<div class="module-page">${pageHeader(title,copy,actions)}${body}</div>`}
function summaryStrip(items){return`<div class="summary-strip cols-${Math.min(4,items.length)}">${items.map(([label,value,copy])=>`<article><small>${esc(label)}</small><strong>${value}</strong><span>${esc(copy)}</span></article>`).join("")}</div>`}
function registerTable(headers,rows,cls=""){return`<div class="register-shell"><table class="register-table ${cls}"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}"><div class="empty">No records found.</div></td></tr>`}</tbody></table></div>`}
function recordLink(route,label){return`<button class="record-link" data-route="${route}">${esc(label)}</button>`}

function crmPage(){const d=state.data,active=d.clients.filter(x=>x.status==="Active").length,rows=d.clients.map(c=>{const projects=d.projects.filter(p=>p.client===c.name).length,quotes=d.quotations.filter(q=>q.client_id===c.id).length,invoices=d.invoices.filter(i=>i.client===c.name),balance=invoices.reduce((n,i)=>n+i.balanceCents,0);return`<tr class="filter-item" data-search="${esc(`${c.name} ${c.contact_name} ${c.email}`.toLowerCase())}" data-status="${esc(c.status)}"><td class="primary-cell"><b>${esc(c.name)}</b><small>${esc(c.contact_name||"No contact recorded")}</small></td><td><a href="mailto:${esc(c.email||"")}">${esc(c.email||"Not recorded")}</a><small>${esc(c.phone||"")}</small></td><td><button class="metric-link" data-route="projects">${projects} project${projects===1?"":"s"}</button><small>${quotes} quotation${quotes===1?"":"s"} · ${invoices.length} invoice${invoices.length===1?"":"s"}</small></td><td>${balance?`<b>${money(balance)}</b><small>Outstanding</small>`:"—"}</td><td>${status(c.status)}</td><td class="actions"><button data-edit-client="${c.id}">Edit</button><button data-route="quotations">Financials</button>${c.status!=="Archived"?`<button class="danger-btn" data-archive-client="${c.id}">Archive</button>`:""}</td></tr>`}).join("");return moduleFrame("CRM","Clients and their connected projects, quotations, invoices and balances.",moduleTools("New client","data-new-client","Search clients…",`<select data-list-status><option value="">All statuses</option><option>Active</option><option>Archived</option></select>`),`${summaryStrip([["Active clients",active,"Current relationships"],["Connected projects",d.projects.length,"Across active mode"],["Open receivables",money(d.metrics.outstandingInvoices),"Recorded invoice balances"]])}${registerTable(["Client","Contact","Connected work","Balance","Status","Actions"],rows,"crm-register")}`)}

function projectsPage(){const d=state.data,atRisk=d.projects.filter(x=>/risk/i.test(x.status)||x.blocker).length,overdue=d.tasks.filter(x=>x.due_date<"2026-10-23"&&!/complete/i.test(x.status)).length,tools=`<div class="module-tools"><input data-list-search placeholder="Search projects, clients or owners…" aria-label="Search projects"><select data-list-status><option value="">All statuses</option><option>Planned</option><option>On track</option><option>At risk</option><option>Completed</option></select><div class="view-switch" aria-label="Project view"><button data-project-view="table" class="${state.projectView==="table"?"active":""}">Table</button><button data-project-view="board" class="${state.projectView==="board"?"active":""}">Board</button></div><button class="primary" data-new-project>New project</button></div>`;
const table=registerTable(["Project","Client","Owner","Progress","Delivery","Due date","Financials","Actions"],d.projects.map(p=>`<tr class="filter-item" data-search="${esc(`${p.name} ${p.client} ${p.owner}`.toLowerCase())}" data-status="${esc(p.status)}"><td class="primary-cell"><b>${esc(p.name)}</b><small>${d.milestones.filter(m=>m.project_id===p.id).length} milestones · ${d.tasks.filter(t=>t.project_id===p.id).length} tasks</small></td><td>${esc(p.client)}</td><td>${esc(p.owner)}</td><td><div class="progress-cell"><b>${p.progress}%</b>${progress(p.progress)}</div></td><td>${status(p.status)}${p.blocker?`<small class="row-warning">${esc(p.blocker)}</small>`:""}</td><td>${fmt(p.due_date)}</td><td><b>${money(p.cost_cents)}</b><small>of ${money(p.budget_cents)}</small></td><td class="actions"><button data-edit-project="${p.id}">Edit</button><button data-new-milestone="${p.id}">Milestone</button><button data-route="team">Tasks</button></td></tr>`).join(""),"project-register");
const groups=["Planned","On track","At risk","Completed"].map(group=>`<section class="kanban-column"><header><h2>${group}</h2><span>${d.projects.filter(p=>p.status===group).length}</span></header>${d.projects.filter(p=>p.status===group).map(p=>`<article class="kanban-card filter-item" data-search="${esc(`${p.name} ${p.client} ${p.owner}`.toLowerCase())}" data-status="${esc(p.status)}"><small>${esc(p.client)}</small><h3>${esc(p.name)}</h3><div class="progress-cell"><b>${p.progress}%</b>${progress(p.progress)}</div><p>${esc(p.owner)} · due ${fmt(p.due_date)}</p>${p.blocker?`<p class="row-warning">${esc(p.blocker)}</p>`:""}<button data-edit-project="${p.id}">Open project</button></article>`).join("")||`<p class="column-empty">No ${group.toLowerCase()} projects</p>`}</section>`).join("");
return moduleFrame("Projects","Delivery plans, owners, milestones, dependencies, evidence and verified completion.",tools,`${summaryStrip([["Active projects",d.projects.filter(x=>x.status!=="Completed").length,"In the current mode"],["At risk",atRisk,"Status or recorded blocker"],["Overdue work",overdue,"Incomplete tasks past due"],["Recorded cost",money(d.projects.reduce((n,p)=>n+p.cost_cents,0)),"Across project records"]])}${state.projectView==="table"?table:`<div class="kanban-board module-list">${groups}</div>`}`)}

function tenderDetailDialog(id){const t=state.data.tenders.find(x=>x.id===id);if(!t)return;dialog(`${t.reference} · Tender readiness`,`<div class="detail-summary"><h3>${esc(t.title)}</h3><p>${esc(t.organisation)} · ${esc(t.category)} · ${t.public_source?"Live public record":"Manual record"}</p>${t.description?`<p class="detail-description">${esc(t.description)}</p>`:""}<div class="detail-metrics"><span><small>Close date</small><b>${fmt(t.close_date)}</b></span><span><small>Relevance</small><b>${esc(t.relevance_label||"Review")} · ${t.relevance_score||0}%</b></span><span><small>Readiness</small><b>${t.readiness.score}%</b></span><span><small>Mandatory verified</small><b>${t.readiness.verified}/${t.readiness.mandatory}</b></span></div><p class="callout">${esc(t.relevance_reason||"Manual relevance review required")}</p><p class="basis">${esc(t.readiness.basis)}</p></div><h3>Submission requirements</h3><ul class="checklist detail-checklist">${t.requirements.map(r=>`<li><button type="button" data-requirement="${r.id}">${r.status==="Verified"?"✓":r.status==="Provided"?"◷":"×"}</button><b>${esc(r.label)}</b><small>${esc(r.status)}${r.document_ref?` · ${esc(r.document_ref)}`:""}</small></li>`).join("")||"<li>No requirements have been recorded. This tender is not submission-ready.</li>"}</ul><div class="button-row"><button type="button" data-new-requirement="${t.id}">Add requirement</button><a class="button-link outline" href="${esc(t.source_url)}" target="_blank" rel="noreferrer">Open official source ↗</a></div>`,async()=>{},"Close");state.dialogSubmit=async()=>{state.dialog=null;render()}}
function tendersPage(){const d=state.data,categories=[...new Set(d.tenders.map(t=>t.category))],ready=d.tenders.filter(t=>t.readiness.submissionReady).length,high=d.tenders.filter(t=>t.relevance_label==="High").length,rows=d.tenders.map(t=>`<tr class="filter-item" data-search="${esc(`${t.reference} ${t.title} ${t.organisation} ${t.description||""} ${t.relevance_reason||""}`.toLowerCase())}" data-category="${esc(t.category)}" data-relevance="${esc(t.relevance_label||"Review")}"><td class="primary-cell"><button class="record-link" data-tender-detail="${t.id}">${esc(t.reference)}</button><small>${esc(t.title)}</small><small>${t.public_source?"Live public record":"Manual record"}</small></td><td>${esc(t.organisation)}<small>${esc(t.category)}</small></td><td><b>${status(`${t.relevance_label||"Review"} · ${t.relevance_score||0}%`)}</b><small class="wrap-copy">${esc(t.relevance_reason||"Manual review required")}</small></td><td>${fmt(t.close_date)}<small>${t.published_date?`Published ${fmt(t.published_date)}`:t.briefing_date?`Briefing ${fmt(t.briefing_date)}`:"Briefing not supplied"}</small></td><td><div class="progress-cell"><b>${t.readiness.score}%</b>${progress(t.readiness.score)}</div><small>${t.readiness.verified}/${t.readiness.mandatory} mandatory verified</small></td><td>${status(t.readiness.submissionReady?"Submission ready":"Not ready")}</td><td class="actions"><button data-tender-detail="${t.id}">Review</button><a href="${esc(t.source_url)}" target="_blank" rel="noreferrer">Official source ↗</a></td></tr>`).join("");const connector=d.connectors.map(c=>`<div class="connector-bar"><span>${uiIcon("briefcase")}</span><div><b>${esc(c.name)}</b><small>Last refresh ${fmt(c.last_refresh)}${c.error?` · ${esc(c.error)}`:""}</small></div>${status(c.status)}<a href="${esc(c.source_url)}" target="_blank" rel="noreferrer">Official portal ↗</a></div>`).join("");return moduleFrame("Tender Radar","Live National Treasury opportunities across all categories, ranked against the company’s electrical-construction profile.",moduleTools("Import tender","data-new-tender","Search title, reference, organisation or description…",`<select data-list-category><option value="">All categories</option>${categories.map(x=>`<option>${esc(x)}</option>`).join("")}</select><select data-list-relevance><option value="">All relevance</option><option>High</option><option>Medium</option><option>Low</option><option>Review</option></select><button id="refresh-tenders">Refresh official tenders</button>`),`${summaryStrip([["Live public tenders",d.tenders.filter(x=>x.public_source).length,"Official OCDS records"],["High relevance",high,"Automated keyword match"],["Submission ready",ready,"Mandatory items verified"],["Needs preparation",d.tenders.length-ready,"Missing or unverified items"]])}<p class="callout">Relevance is an explainable keyword-based aid, not an eligibility decision. Confirm scope, compulsory briefings and every tender document before bidding.</p><div class="connector-stack">${connector}</div>${registerTable(["Tender","Organisation","Relevance","Dates","Readiness","Status","Actions"],rows,"tender-register")}`)}

function fundingPage(){const d=state.data,rows=d.funding.map(f=>{const missing=f.documents.filter(x=>x.status!=="Verified").length;return`<tr class="filter-item" data-search="${esc(`${f.type} ${f.purpose} ${f.provider} ${f.po_reference}`.toLowerCase())}"><td class="primary-cell"><b>${esc(f.purpose)}</b><small>${esc(f.type)} · ${esc(f.po_reference||"No PO reference")}</small></td><td>${esc(f.project_name||f.invoice_number||"Operational funding")}</td><td><b>${money(f.requiredCents)}</b><small>${money(f.availableCents)} confirmed</small></td><td><b class="lime">${money(f.gapCents)}</b><small>${esc(f.assumption)}</small></td><td>${status(f.status)}<small>${missing} document${missing===1?"":"s"} outstanding</small></td><td class="actions"><button data-new-funding-doc="${f.id}">Checklist</button></td></tr>`}).join("");return moduleFrame("Funding","Recorded funding needs, linked business records and document-readiness checklists.",moduleTools("New funding need","data-new-funding","Search funding records…"),`${summaryStrip([["Total required",money(d.funding.reduce((n,f)=>n+f.requiredCents,0)),"Explicit recorded costs"],["Confirmed funds",money(d.funding.reduce((n,f)=>n+f.availableCents,0)),"Available amounts"],["Funding gap",money(d.metrics.fundingNeeded),"No offer or eligibility inferred"]])}${registerTable(["Purpose","Linked record","Requirement","Gap and basis","Application","Actions"],rows,"funding-register")}`)}

function quotationsPage(){const d=state.data,rows=d.quotations.map(q=>`<tr class="filter-item" data-search="${esc(`${q.number} ${q.client} ${q.service_title||q.description}`.toLowerCase())}"><td class="primary-cell"><b>${esc(q.number)}</b><small>Issued ${fmt(q.issue_date)} · valid to ${fmt(q.valid_until)} · Rev ${q.revision||1}</small></td><td>${esc(q.client||"Unlinked client")}<small>${esc(q.project_name||"General quotation")}</small></td><td class="description-cell"><b>${esc(q.service_title||"Quotation")}</b><small>${esc(q.description)}</small></td><td><b>${money(q.total_cents)}</b><small>${q.tax_rate}% tax · ${q.items?.length||1} line item${(q.items?.length||1)===1?"":"s"}</small></td><td>${status(q.status)}</td><td class="actions"><button data-preview-record="quotation:${q.id}">Preview</button>${!q.invoice_id?`<button data-edit-quote="${q.id}">Edit</button><button data-convert-quote="${q.id}">Convert</button>`:`<span>${esc(q.invoice_number||"Invoiced")}</span>`}</td></tr>`).join("");const invoiceRows=d.invoices.map(i=>`<tr class="filter-item" data-search="${esc(`${i.number} ${i.client} ${i.project_name||""}`.toLowerCase())}"><td class="primary-cell"><b>${esc(i.number)}</b><small>Due ${fmt(i.due_date)}</small></td><td>${esc(i.client)}<small>${esc(i.project_name||"General invoice")}</small></td><td>${money(i.total_cents)}</td><td>${money(i.paidCents)}</td><td><b>${money(i.balanceCents)}</b></td><td>${status(i.status)}</td><td class="actions"><button data-preview-record="invoice:${i.id}">Preview</button>${i.balanceCents?`<button data-payment="${i.id}">Payment</button>`:""}</td></tr>`).join("");return moduleFrame("Quotations & Invoices","Build itemised quotations, preview totals, convert accepted work and record protected payments.",moduleTools("Create quotation","data-new-quote","Search number, client, project or scope…"),`${summaryStrip([["Open quotations",d.quotations.filter(x=>x.status!=="Converted").length,"Draft and issued"],["Invoice revenue",money(d.metrics.revenue),"Issued records"],["Receivables",money(d.metrics.outstandingInvoices),"After recorded payments"]])}<section class="register-section"><header><h2>Quotations</h2></header>${registerTable(["Quotation","Client / project","Scope","Total","Status","Actions"],rows)}</section><section class="register-section"><header><h2>Invoices & balances</h2></header>${registerTable(["Invoice","Client / project","Total","Paid","Balance","Status","Actions"],invoiceRows)}</section>`)}

function compliancePage(){const d=state.data,categories=[...new Set(d.compliance.map(c=>c.category||"Other"))],rows=d.compliance.map(c=>`<tr class="filter-item" data-search="${esc(`${c.title} ${c.standard_ref} ${c.owner} ${c.authority} ${c.applicability}`.toLowerCase())}" data-status="${esc(c.status)}" data-category="${esc(c.category||"Other")}"><td class="primary-cell"><b>${esc(c.title)}</b><small>${esc(c.standard_ref||"Internal requirement")}</small></td><td>${esc(c.category||"Other")}<small>${esc(c.authority||"Responsible authority to confirm")}</small></td><td class="wrap-copy">${esc(c.applicability||"Confirm applicability")}<small>${esc(c.frequency||"Frequency to confirm")}</small></td><td>${esc(c.owner)}<small>${c.mandatory?"Marked required":"Conditional / review"}</small></td><td>${esc(c.evidence||"No evidence recorded")}<small>${c.expiry_date?`Expiry ${fmt(c.expiry_date)}`:"No expiry recorded"}</small></td><td>${status(c.status)}</td><td class="actions"><button data-edit-compliance="${c.id}">Update</button></td></tr>`).join("");const review=d.compliance.filter(c=>c.status==="Review applicability").length,evidence=d.compliance.filter(c=>["Evidence required","Non-compliant"].includes(c.status)).length,compliant=d.compliance.filter(c=>c.status==="Compliant").length;return moduleFrame("Compliance","South African business compliance baseline plus project- and tender-specific controls, ownership and evidence.",moduleTools("New requirement","data-new-compliance","Search requirement, authority or applicability…",`<select data-list-category><option value="">All categories</option>${categories.map(x=>`<option>${esc(x)}</option>`).join("")}</select><select data-list-status><option value="">All statuses</option><option>Review applicability</option><option>Evidence required</option><option>Under review</option><option>Expiring soon</option><option>Compliant</option><option>Non-compliant</option></select>`),`${summaryStrip([["Baseline & controls",d.compliance.length,"Active-mode register"],["Review applicability",review,"Confirm with adviser or authority"],["Evidence required",evidence,"Missing or non-compliant"],["Compliant",compliant,"Evidence recorded"]])}<p class="callout warn">This is an operational baseline, not a guarantee of complete legal compliance or legal advice. Confirm applicability, deadlines and evidence for the company structure, workforce, projects and each tender condition.</p>${registerTable(["Requirement","Category / authority","Applicability / cycle","Owner","Evidence / expiry","Status","Action"],rows)}`)}

function documentsPage(){const d=state.data,rows=d.documents.map(x=>`<tr class="filter-item" data-search="${esc(`${x.title} ${x.file_name} ${x.related_name||x.related_type}`.toLowerCase())}" data-status="${esc(x.status)}"><td class="primary-cell"><b>${esc(x.title)}</b><small>${esc(x.file_name)} · ${fmt(x.created_at)}</small></td><td>${esc(x.related_name||x.related_type||"General")}</td><td>Rev ${x.revision}</td><td>${esc(x.uploader)}</td><td>${status(x.status)}</td><td class="actions"><a href="/api/documents/${x.id}/download?preview=1" target="_blank" data-auth-link>Preview</a><a href="/api/documents/${x.id}/download" data-auth-link>Download</a>${x.status!=="Archived"?`<button data-archive-document="${x.id}">Archive</button>`:""}</td></tr>`).join("");return moduleFrame("Documents","Searchable evidence with related-record links, revisions, previews and archive status.",moduleTools("Upload document","data-new-document","Search title, file or linked record…",`<select data-list-status><option value="">All statuses</option><option>Current</option><option>Superseded</option><option>Archived</option></select>`),`${registerTable(["Document","Linked record","Revision","Uploaded by","Status","Actions"],rows)}<p class="basis register-note">Uploads are limited to 1 MB in this local build. Uploading the same title creates a new revision and supersedes the previous current version.</p>`)}

function settingsPage(){
  const d=state.data,tab=state.settingsTab,nav=`<div class="settings-tabs" role="tablist"><button data-settings-tab="profile" class="${tab==="profile"?"active":""}">Profile</button><button data-settings-tab="company" class="${tab==="company"?"active":""}">Company & access</button><button data-settings-tab="integrations" class="${tab==="integrations"?"active":""}">Integrations</button></div>`;
  let body;
  if(tab==="company")body=`<div class="settings-layout"><form class="settings-card" id="company-form"><header><h2>Company settings</h2><span>${status(`${d.mode} Mode`)}</span></header><p>These details are isolated to the active mode.</p><label>Company name<input name="companyName" value="${esc(d.settings?.company_name||"")}" required></label><label>Email<input name="email" type="email" value="${esc(d.settings?.email||"")}"></label><label>Phone<input name="phone" value="${esc(d.settings?.phone||"")}"></label><button class="primary" ${d.permissions.director?"":"disabled"}>Save company</button></form><section class="settings-card"><h2>People & permissions</h2><p>Signed in as <b>${esc(d.user.role)}</b>. Role permissions are enforced by business services.</p><ul class="simple-list">${d.users.map(u=>`<li><span><b>${esc(u.name)}</b><small>${esc(u.role)}</small></span>${status(u.active?"Active":"Inactive")}</li>`).join("")}</ul></section></div>`;
  else if(tab==="integrations")body=`<div class="settings-layout"><section class="settings-card integration-card"><header><h2>Business data services</h2>${status(d.runtime.openedgeActive?"Connected":"Attention")}</header><dl><div><dt>Operational repository</dt><dd>${esc(d.runtime.database)}</dd></div><div><dt>OpenEdge ABL assets</dt><dd>${d.runtime.openedgeVerified?"Schema, validation and deterministic calculations verified":"Verification failed"}</dd></div><div><dt>PAS for OpenEdge</dt><dd>${d.runtime.openedgeActive?"Active · authenticated WEB transport":"Unavailable"}</dd></div></dl><p class="service-impact">Browser writes are validated and committed to OpenEdge; SQLite is a replaceable compatibility cache and restores from OpenEdge on restart.</p></section><section class="settings-card integration-card"><header><h2>Wayne & LiveAvatar</h2>${status(d.runtime.avatarConfigured?"Sandbox ready":"Unavailable")}</header><dl><div><dt>LiveAvatar</dt><dd>${d.runtime.avatarConfigured?`${d.runtime.avatarLimitSeconds}-second zero-payment sandbox configured`:"Authorised sandbox configuration missing"}</dd></div><div><dt>Business context</dt><dd>${d.runtime.avatarBusinessContext?"Supplied through declared provider variables":"Companion briefing only"}</dd></div><div><dt>Provider boundary</dt><dd>${esc(d.runtime.avatarCapabilityReason)}</dd></div></dl><p class="service-impact">No paid OpenAI fallback is enabled. Meetings continue independently. Provider transcripts are saved only to the active mode and user.</p></section><section class="settings-card integration-card"><header><h2>Email & notifications</h2>${status(d.runtime.emailConfigured?"SMTP configured":"Preview / awaiting setup")}</header><dl><div><dt>Delivery mode</dt><dd>${esc(d.runtime.emailMode)}</dd></div><div><dt>Timezone</dt><dd>${esc(d.runtime.timezone)}</dd></div><div><dt>Missing server settings</dt><dd>${esc((d.runtime.emailStatus?.missing||[]).join(", ")||"None")}</dd></div></dl><form id="email-test-form"><label>Explicit test recipient<input name="recipient" type="email" placeholder="name@example.com" required></label><label class="confirm"><input name="confirmed" type="checkbox" required> Send one deliberate test message to this address.</label><button class="outline" ${d.runtime.emailConfigured&&d.permissions.director?"":"disabled"}>Send test email</button></form><p class="service-impact">Demo meetings always use preview. No message is marked sent unless SMTP confirms acceptance.</p></section></div>`;
  else body=`<div class="settings-layout profile-settings"><form class="settings-card" id="profile-form"><header><h2>My profile</h2><span class="avatar large">${esc((d.user.preferredName||d.user.name)[0])}</span></header><p>Wayne uses your preferred name in authorised conversations.</p><label>Account name<input value="${esc(d.user.name)}" disabled></label><label>Preferred name<input name="preferredName" value="${esc(d.user.preferredName)}" required></label><label>Pronunciation guidance<input name="pronunciation" value="${esc(d.user.pronunciation||"")}" placeholder="Optional guidance for voice interactions"></label><button class="primary">Save profile</button></form><section class="settings-card mode-card"><header><h2>Workspace mode</h2>${status(`${d.mode} Mode`)}</header><p>${d.mode==="DEMO"?"Fictional demonstration records are isolated from Real Mode.":"Operational records in Real Mode are isolated from Demo Mode."}</p><ul class="feature-list"><li>Records, documents and conversations are mode-scoped</li><li>Meetings and notification jobs never cross modes</li><li>Demo email remains in preview unless explicitly test-sent</li></ul><button id="settings-mode-switch" class="outline">Switch to ${d.mode==="DEMO"?"Real":"Demo"} Mode</button></section></div>`;
  return moduleFrame("Settings","Profile, organisation, access controls and administrator integration status.","",`${nav}${body}`)
}
function genericPage(){const label=nav.find(x=>x[0]===state.route)?.[2]||"Records";return`${pageHeader(label,"A focused view of authorised records and workflows.")}<div class="empty-card"><span>▤</span><h2>${label}</h2><p>No ${label.toLowerCase()} records are present in ${state.data.mode} Mode. Use Projects, Tenders, Funding, Finance, Team & Tasks, AI Meetings or Wayne for connected operational records.</p><button data-route="dashboard" class="outline">Return to dashboard</button></div>`}
function empty(title,copy){return`<div class="empty"><b>${title}</b><span>${copy}</span></div>`}
function main(){if(state.route==="dashboard")return dashboard();if(state.route==="crm")return crmPage();if(state.route==="projects")return projectsPage();if(state.route==="team")return tasksPage();if(state.route==="quotations")return quotationsPage();if(state.route==="tenders")return tendersPage();if(state.route==="funding")return fundingPage();if(state.route==="finance")return financePage();if(state.route==="compliance")return compliancePage();if(state.route==="documents")return documentsPage();if(state.route==="meetings")return meetingsPage();if(state.route==="reports")return reportsPage();if(state.route==="settings")return settingsPage();return genericPage()}
function wayneMeetingLabel(meeting){const when=new Date(meeting.started_at).toLocaleString("en-ZA",{timeZone:"Africa/Johannesburg",day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:false}),capture=meeting.transcript_revision>0?meeting.transcript_completeness:"No transcript captured";return`${meeting.title||"Untitled meeting"} — ${when} · ${capture}`}
function wayneMeetingSetup(){const history=(state.data.wayneMeetings||[]).filter(x=>x.status!=="Deleted"&&!x.active_provider_session);return`<div class="wayne-meeting-setup"><h3>Optional follow-up</h3><p class="basis">Start immediately for a fresh conversation, continue the latest saved discussion, or select one authorised recording. History is supplied only to the next explicitly started session.</p><label>Recorded meeting<select id="wayne-followup-select"><option value="">Fresh conversation — do not continue history</option><option value="__last__" ${waynePrefs.followUpId==="__last__"?"selected":""}>From Last Session</option>${history.map(x=>`<option value="${esc(x.id)}" ${x.id===waynePrefs.followUpId?"selected":""}>${esc(wayneMeetingLabel(x))}</option>`).join("")}</select></label></div>`}
function wayneDraftMarkup(draft){const minutes=draft.kind==="meeting-minutes";return`<article class="wayne-email-draft"><b>${minutes?"Meeting minutes email — prepared, not sent":"Suggested email draft"}</b>${minutes?`<small>To: ${esc(draft.recipient)}</small>`:""}<strong>${esc(draft.subject||"Meeting minutes unavailable")}</strong><pre>${esc(draft.body||draft.reason||"")}</pre><div class="button-row"><button class="outline" data-copy-draft="${esc(`${draft.subject||""}\n\n${draft.body||draft.reason||""}`)}">Copy draft</button>${minutes&&draft.ready?`<button class="primary" data-review-minutes-email="${esc(draft.meetingId)}">${draft.deliveryConfigured?"Review & send":"Review delivery setup"}</button>`:""}</div>${minutes?`<small>${esc(draft.deliveryStatus||draft.reason||"")}</small>`:""}</article>`}
function wayne(){if(!state.wayneOpen)return"";const runtime=state.data.runtime;return`<div class="modal-back wayne-room-back"><section class="wayne-modal wayne-room" id="wayne-room"><header class="wayne-room-header"><div class="wayne-mini">W</div><span><h2>Meeting with Wayne</h2><small>Operations assistant · ${state.data.mode} Mode</small></span><div class="wayne-session-clock"><b id="wayne-countdown">01:00</b><small id="wayne-timer-basis">Local 60-second estimate</small></div><button id="wayne-panel-toggle" class="outline" aria-expanded="${waynePrefs.panelOpen}">${waynePrefs.panelOpen?"Hide":"Show"} panel</button><button data-close aria-label="Close Wayne meeting">×</button></header><div class="wayne-room-body ${waynePrefs.panelOpen?"":"panel-collapsed"}"><main class="wayne-video-area"><div class="wayne-stage"><video id="wayne-video" autoplay playsinline aria-label="Wayne LiveAvatar video"></video><audio id="wayne-audio" autoplay></audio><div class="wayne-stage-state" id="wayne-avatar-state">Ready to start</div><div class="wayne-self-view"><video id="wayne-self-video" autoplay playsinline muted aria-label="Your local camera preview"></video><span id="wayne-camera-placeholder">Camera off</span><small>You · local preview</small></div></div><div class="ai-status ${runtime.avatarConfigured?"good":"warn"}" id="wayne-provider-status">${runtime.avatarConfigured?`LiveAvatar sandbox ready · ${runtime.avatarLimitSeconds}s maximum.`:"LiveAvatar unavailable: authorised sandbox configuration is missing."}</div><div class="wayne-presentation-context" id="wayne-presentation-context" hidden></div></main><aside class="wayne-side-panel" id="wayne-side-panel"><nav><button data-wayne-tab="agenda" class="${waynePrefs.panelTab==="agenda"?"active":""}">Agenda</button><button data-wayne-tab="transcript" class="${waynePrefs.panelTab==="transcript"?"active":""}">Transcript</button><button data-wayne-tab="records" class="${waynePrefs.panelTab==="records"?"active":""}">Business records</button></nav><section data-wayne-panel="agenda" class="${waynePrefs.panelTab==="agenda"?"active":""}">${wayneMeetingSetup()}<label>Meeting notes<textarea id="wayne-notes" placeholder="Notes stay visible when Wayne restarts.">${esc(waynePrefs.notes)}</textarea></label></section><section data-wayne-panel="transcript" class="${waynePrefs.panelTab==="transcript"?"active":""}"><h3>Live transcript</h3><div id="wayne-avatar-transcript" class="avatar-transcript"><p class="transcript-empty">Transcript events will appear here.</p></div><div id="wayne-email-drafts" class="wayne-email-drafts">${avatarRuntime.emailDrafts.map(wayneDraftMarkup).join("")}</div></section><section data-wayne-panel="records" class="${waynePrefs.panelTab==="records"?"active":""}"><h3>Authorised snapshot</h3><p class="basis">Non-AI record summaries from the active workspace mode.</p><div id="wayne-avatar-sources" class="sources"><span class="basis">Start Wayne to refresh supporting records.</span></div></section></aside></div><footer class="wayne-controls"><button class="primary" id="wayne-avatar-start" ${runtime.avatarConfigured?"":"disabled"}>Start Wayne</button><button class="outline" id="wayne-present-current" disabled>Present page</button><button class="outline" id="wayne-avatar-mic" disabled>Microphone off</button><button class="outline" id="wayne-camera">Camera off</button><button class="outline" id="wayne-fullscreen">Fullscreen</button><button class="outline" id="wayne-fullscreen-fallback" hidden>Enter fullscreen</button><button class="outline" id="wayne-restart" ${runtime.avatarConfigured?"":"disabled"}>Restart Wayne</button><button class="outline" id="wayne-stop-presenting" hidden>Stop presenting</button><button class="danger-btn" id="wayne-avatar-end" disabled>End meeting</button></footer></section></div>`}

function avatarCommand(event_type,payload={}){const room=avatarRuntime.room,session=avatarRuntime.session;if(!room||!session)return;room.localParticipant.publishData(new TextEncoder().encode(JSON.stringify({event_id:crypto.randomUUID(),event_type,session_id:session.sessionId,...payload})),{reliable:true,topic:"agent-control"}).catch(error=>avatarState(`Command failed: ${error.message}`))}
function avatarState(message){const node=document.querySelector("#wayne-avatar-state");if(node)node.textContent=message}
function transcriptStatus(message,tone=""){const node=document.querySelector("#wayne-transcript-status");if(node){node.textContent=message;node.className=`wayne-transcript-status ${tone}`.trim()}}
function avatarTranscript(role,text,{isFinal=true,eventId=null,occurredAt=null}={}){const node=document.querySelector("#wayne-avatar-transcript");if(!node)return;const wasPinned=avatarRuntime.transcriptPinned,nodeKey=CSS.escape(String(eventId||role)),selector=`[data-live-transcript="${nodeKey}"]`;node.querySelector(".transcript-empty")?.remove();let row=!isFinal?node.querySelector(selector):null;if(!row){row=document.createElement("p");row.dataset.liveTranscript=nodeKey;node.append(row)}row.classList.toggle("provisional",!isFinal);row.innerHTML=`<b>${role==="assistant"?"Wayne":"You"}:</b> <span>${esc(text)}</span><time>${new Date(occurredAt||Date.now()).toLocaleTimeString("en-ZA",{hour:"2-digit",minute:"2-digit",second:"2-digit"})}</time>`;if(isFinal)delete row.dataset.liveTranscript;if(wasPinned)node.scrollTop=node.scrollHeight}
function bindTranscriptScroll(){const node=document.querySelector("#wayne-avatar-transcript");if(!node||node.dataset.scrollBound)return;node.dataset.scrollBound="1";node.addEventListener("scroll",()=>{avatarRuntime.transcriptPinned=node.scrollHeight-node.scrollTop-node.clientHeight<48})}
async function copyWayneDraft(button){try{await navigator.clipboard.writeText(button.dataset.copyDraft||"");button.textContent="Copied"}catch{avatarState("Copy unavailable. Select the draft text manually.")}}
function bindWayneDrafts(){document.querySelectorAll("[data-copy-draft]").forEach(button=>button.onclick=()=>copyWayneDraft(button));document.querySelectorAll("[data-review-minutes-email]").forEach(button=>button.onclick=()=>showMinutesEmailReview(avatarRuntime.emailDrafts.find(draft=>draft.kind==="meeting-minutes"&&draft.meetingId===button.dataset.reviewMinutesEmail)))}
function showMinutesEmailReview(draft){if(!draft)return;document.querySelector("#wayne-minutes-review")?.remove();const room=document.querySelector("#wayne-room");if(!room)return;room.insertAdjacentHTML("beforeend",`<div class="wayne-disclosure-review" id="wayne-minutes-review"><section><header><span><h2>Send meeting minutes</h2><small>External email · explicit confirmation required</small></span><button type="button" data-minutes-cancel aria-label="Cancel email review">×</button></header><p class="privacy-warning">Review the transcript-derived minutes below. They will be sent externally only after confirmation.</p><p><b>To:</b> ${esc(draft.recipient)}</p><p><b>Subject:</b> ${esc(draft.subject)}</p><pre class="minutes-email-preview">${esc(draft.body)}</pre><p class="form-error" id="wayne-minutes-error"></p><label class="confirm"><input type="checkbox" id="wayne-minutes-confirm"> I confirm these minutes and the recipient ${esc(draft.recipient)}.</label><footer><button class="outline" type="button" data-minutes-cancel>Cancel</button><button class="primary" id="wayne-minutes-send" disabled>Send meeting minutes</button></footer></section></div>`);document.querySelectorAll("[data-minutes-cancel]").forEach(button=>button.onclick=()=>document.querySelector("#wayne-minutes-review")?.remove());const checkbox=document.querySelector("#wayne-minutes-confirm"),send=document.querySelector("#wayne-minutes-send");checkbox.onchange=()=>send.disabled=!checkbox.checked;send.onclick=async()=>{send.disabled=true;send.textContent="Sending…";try{const result=await api(`/api/avatar/meetings/${draft.meetingId}/minutes-email`,{method:"POST",body:JSON.stringify({recipient:draft.recipient,confirmed:true})});document.querySelector("#wayne-minutes-review")?.remove();avatarState(`Meeting minutes sent to ${result.recipient}.`);draft.deliveryStatus="Sent"}catch(error){const node=document.querySelector("#wayne-minutes-error");if(node)node.textContent=error.message;send.disabled=false;send.textContent="Retry send"}}}
function showWayneDraft(draft){if(!draft)return;avatarRuntime.emailDrafts.push(draft);const box=document.querySelector("#wayne-email-drafts");if(box){box.insertAdjacentHTML("beforeend",wayneDraftMarkup(draft));bindWayneDrafts()}selectWaynePanel("transcript")}
function presentationRequest(){return state.presentation.route?{route:state.presentation.route,reportPeriod:state.reportPeriod,tenderFilters:{...state.tenderFilters},filters:{...(state.presentationFilters[state.presentation.route]||{})}}:null}
function bindPresentedPage(){
  document.querySelectorAll("[data-route]").forEach(link=>link.onclick=event=>{event.preventDefault();navigateDuringWayne(link.dataset.route,{present:state.presentation.active})});
  const remembered=state.presentationFilters[state.route]||{};
  const apply=()=>{const q=(document.querySelector("[data-list-search]")?.value||"").toLowerCase(),cat=document.querySelector("[data-list-category]")?.value||"",rel=document.querySelector("[data-list-relevance]")?.value||"",statusFilter=document.querySelector("[data-list-status]")?.value||"";state.presentationFilters[state.route]={search:q,category:cat,relevance:rel,status:statusFilter};if(state.route==="tenders")state.tenderFilters={search:q,category:cat,relevance:rel};document.querySelectorAll(".filter-item").forEach(item=>item.hidden=!(item.dataset.search||"").includes(q)||(cat&&item.dataset.category!==cat)||(rel&&item.dataset.relevance!==rel)||(statusFilter&&item.dataset.status!==statusFilter));if(state.presentation.active)void loadPresentationContext()};
  const search=document.querySelector("[data-list-search]"),category=document.querySelector("[data-list-category]"),relevance=document.querySelector("[data-list-relevance]"),statusFilter=document.querySelector("[data-list-status]");if(search){search.value=remembered.search??(state.route==="tenders"?state.tenderFilters.search:"");search.oninput=apply}if(category){category.value=remembered.category??(state.route==="tenders"?state.tenderFilters.category:"");category.onchange=apply}if(relevance){relevance.value=remembered.relevance??(state.route==="tenders"?state.tenderFilters.relevance:"");relevance.onchange=apply}if(statusFilter){statusFilter.value=remembered.status||"";statusFilter.onchange=apply}apply();
  const reportPeriod=document.querySelector("#report-period");if(reportPeriod)reportPeriod.onchange=event=>{state.reportPeriod=event.target.value;refreshPresentedPage();void loadPresentationContext()};
  document.querySelectorAll("[data-auth-link]").forEach(link=>link.onclick=async event=>{event.preventDefault();try{const response=await fetch(link.href,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error((await response.json()).error||"Download failed");const blob=await response.blob(),url=URL.createObjectURL(blob);window.open(url,"_blank","noopener");setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(error){toast(error.message,true)}});
}
function refreshPresentedPage(){const content=document.querySelector(".content");if(!content)return;content.innerHTML=main();document.title=browserTitle();document.querySelectorAll(".sidebar [data-route]").forEach(link=>link.classList.toggle("active",link.dataset.route===state.route));bindPresentedPage()}
function navigateDuringWayne(route,{present=false}={}){if(!canOpenPresentationRoute(route,state.data.permissions,state.data.user.role)){avatarState(`Access denied: ${route} is not authorised for this account.`);toast("That section is not authorised for this account.",true);return false}state.route=route;history.replaceState(null,"",`#${route}`);state.presentation.route=route;refreshPresentedPage();if(present)enterPresentation();else avatarState(`${nav.find(item=>item[0]===route)?.[2]||route} opened. Say “present this page” to show it beside Wayne.`);return true}
async function loadPresentationContext(){if(!state.presentation.route)return;const node=document.querySelector("#wayne-presentation-context");if(node){node.hidden=false;node.innerHTML="<b>Preparing visible-page context…</b>"}try{const context=await api("/api/avatar/presentation-context",{method:"POST",body:JSON.stringify(presentationRequest())});state.presentation.context=context;waynePrefs.presentationContext=presentationRequest();if(node)node.innerHTML=`<b>${esc(context.label)} is visible</b><span>${esc(context.summary)}</span><small>LiveAvatar receives context only when a session starts. Wayne may not know changed filters during this active session.</small><button class="outline" id="wayne-restart-with-page">Review context and restart Wayne</button>`;document.querySelector("#wayne-restart-with-page")?.addEventListener("click",()=>reviewWayneSession(avatarRuntime.sessionType,{restart:true}))}catch(error){state.presentation.context=null;if(node)node.innerHTML=`<b>Page context unavailable</b><span>${esc(error.message)}</span>`}}
function enterPresentation(){if(!avatarRuntime.session||!avatarRuntime.room){avatarState("Start Wayne before presenting the application.");return}state.presentation.active=true;state.presentation.route=state.route;document.body.classList.add("wayne-presenting");bindPresentedPage();document.querySelector("#wayne-stop-presenting")?.removeAttribute("hidden");document.querySelector("#wayne-present-current")?.setAttribute("hidden","");document.querySelector("#wayne-room")?.setAttribute("aria-label",`Wayne presenting ${nav.find(item=>item[0]===state.route)?.[2]||state.route}`);void loadPresentationContext();avatarState(`${nav.find(item=>item[0]===state.route)?.[2]||state.route} presentation is visible.`)}
async function exitPresentation(){state.presentation.active=false;state.presentation.fullscreenPending=false;document.body.classList.remove("wayne-presenting");document.querySelector("#wayne-stop-presenting")?.setAttribute("hidden","");document.querySelector("#wayne-present-current")?.removeAttribute("hidden");document.querySelector("#wayne-fullscreen-fallback")?.setAttribute("hidden","");document.querySelector("#wayne-presentation-context")?.setAttribute("hidden","");if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});avatarState("Wayne meeting room restored.")}
async function requestPresentationFullscreen(){if(!state.presentation.active)enterPresentation();const target=document.querySelector(".shell");try{if(!document.fullscreenElement)await target.requestFullscreen();state.presentation.fullscreenPending=false;document.querySelector("#wayne-fullscreen-fallback")?.setAttribute("hidden","");avatarState("Application presentation is fullscreen.")}catch{state.presentation.fullscreenPending=true;const fallback=document.querySelector("#wayne-fullscreen-fallback");fallback?.removeAttribute("hidden");avatarState("Browser approval is required. Select Enter fullscreen.")}}
async function executePresentationCommand(command,expectedSessionId){if(avatarRuntime.session?.id!==expectedSessionId)return;if(command.type==="unknown-route"){avatarState(`I cannot open “${command.label}”. Choose an INFINITE-X OS sidebar section.`);return}if(command.type==="open"){if(navigateDuringWayne(command.route,{present:command.present}))avatarState(`${nav.find(item=>item[0]===command.route)?.[2]} opened${command.present?" in presentation mode":""}.`);return}if(command.type==="present-current"){enterPresentation();return}if(command.type==="fullscreen"){await requestPresentationFullscreen();return}if(command.type==="stop-presenting"){await exitPresentation()}}
async function handlePresentationTranscript({text,providerEventId,isFinal,role,sessionId}){const command=parsePresentationCommand(text);if(!command||!acceptPresentationEvent({text,providerEventId,isFinal,role,sessionId},avatarRuntime.session?.id,avatarRuntime.commandEvents))return;await executePresentationCommand(command,sessionId)}
async function saveAvatarEvent(event){const key=transcriptEventKey(event);if(avatarRuntime.savedEvents.has(key))return;try{const result=await api("/api/avatar/session/event",{method:"POST",body:JSON.stringify({id:event.localSessionId,role:event.role,content:event.text,providerEventId:event.providerEventId,occurredAt:event.occurredAt})});avatarRuntime.savedEvents.add(key);avatarTranscript(event.role,event.text,{isFinal:true,eventId:event.role,occurredAt:event.occurredAt});transcriptStatus(result.repository?.source==="OpenEdge"?"Transcript saved to OpenEdge.":"Transcript captured.","good");await handlePresentationTranscript({text:event.text,providerEventId:event.providerEventId,isFinal:true,role:event.role,sessionId:event.localSessionId});if(result?.emailDraft)showWayneDraft(result.emailDraft);if(result?.minutesEmailDraft){showWayneDraft(result.minutesEmailDraft);selectWaynePanel("transcript");avatarState(result.minutesEmailDraft.ready?"Meeting minutes prepared for review. They have not been sent.":result.minutesEmailDraft.reason)}}catch(error){transcriptStatus(`Transcript persistence error: ${error.message}`,"bad");avatarState(`Transcript save pending: ${error.message}`);throw error}}
function handleLiveAvatarMessage(message,expectedSessionId){const active=avatarRuntime.session;if(!active||active.id!==expectedSessionId)return;const event=parseLiveAvatarEvent(message,{localSessionId:expectedSessionId,providerSessionId:active.sessionId});if(!event)return;if(event.kind==="transcript"){if(event.role==="user")avatarRuntime.userTranscriptSeen=true;clearTimeout(avatarRuntime.transcriptTimer);if(!event.isFinal){avatarTranscript(event.role,event.text,{isFinal:false,eventId:event.role,occurredAt:event.occurredAt});transcriptStatus("Receiving transcript…","active");return}transcriptStatus("Receiving transcript…","active");const task=saveAvatarEvent(event);avatarRuntime.pendingEventSaves.add(task);task.finally(()=>avatarRuntime.pendingEventSaves.delete(task)).catch(()=>{});return}if(event.eventType==="user.speak_started"){avatarRuntime.userTranscriptSeen=false;transcriptStatus("Listening…","active");clearTimeout(avatarRuntime.transcriptTimer)}if(event.eventType==="user.speak_ended"){transcriptStatus("Processing speech…","active");clearTimeout(avatarRuntime.transcriptTimer);avatarRuntime.transcriptTimer=setTimeout(()=>{if(!avatarRuntime.userTranscriptSeen)transcriptStatus("Speech was detected, but no transcript was received.","bad")},8000)}if(event.eventType==="avatar.speak_started")avatarState("Wayne is speaking");if(event.eventType==="avatar.speak_ended")avatarState("Ready to listen");if(event.eventType==="session.stopped"){avatarState("Ending session…");void stopAvatar({status:"Session ended",keepMeetingOpen:true})}}
