  const rows=Object.entries(preflight.outboundContext||{}).map(([key,value])=>`<details><summary>${esc(key.replaceAll("_"," "))}</summary><p>${esc(value)}</p></details>`).join("");room.insertAdjacentHTML("beforeend",`<div class="wayne-disclosure-review" id="wayne-disclosure-review"><section><header><span><h2>Review information sent to Wayne</h2><small>${esc(preflight.label)} · balance ${esc(preflight.balance)} credits · expected usage ${esc(preflight.expectedCredits)} credits</small></span><button type="button" data-review-cancel aria-label="Cancel context review">×</button></header><p class="privacy-warning">${esc(preflight.warning)}</p><p>${esc(preflight.microphoneNotice)}</p><div class="outbound-categories"><b>Disclosure categories</b><span>${(preflight.categories||[]).map(esc).join(" · ")}</span></div><div class="outbound-context">${rows}</div><p class="basis">${esc(preflight.retentionNotice)}</p><label class="confirm"><input type="checkbox" id="wayne-disclosure-confirm"> I confirm this balance, expected usage and outbound context.</label><footer><button class="outline" type="button" data-review-cancel>Cancel</button><button class="primary" id="wayne-disclosure-start" disabled>Confirm and ${restart?"restart":"start"} ${esc(preflight.label.toLowerCase())}</button></footer></section></div>`);
