function dialog(title,body,submit,label="Save"){state.dialog=`<div class="modal-back dialog"><form id="dialog-form"><header><h2>${title}</h2><button type="button" data-dialog-close>×</button></header>${body}<p class="form-error" id="dialog-error"></p><div class="button-row"><button type="button" data-dialog-close>Cancel</button><button class="primary">${label}</button></div></form></div>`;state.dialogSubmit=submit;render()}
