function clientDialog(id=""){const c=state.data.clients.find(x=>x.id===id)||{};dialog(id?"Edit client":"New client",`<label>Client name<input name="name" value="${esc(c.name||"")}" required></label><label>Contact name<input name="contactName" value="${esc(c.contact_name||"")}"></label><label>Email<input name="email" type="email" value="${esc(c.email||"")}"></label><label>Phone<input name="phone" value="${esc(c.phone||"")}"></label><label>Notes<textarea name="notes">${esc(c.notes||"")}</textarea></label>`,data=>api(id?`/api/clients/${id}/edit`:"/api/clients",{method:"POST",body:JSON.stringify(data)}),id?"Save changes":"Create client")}
