function quoteLineRow(item={}){return`<div class="quote-line" data-quote-line><label>Description<input data-line-description value="${esc(item.description||"")}" placeholder="e.g. Supply and install LED fittings" required></label><label>Qty<input data-line-quantity type="number" min="0.01" step="0.01" value="${item.quantity||1}" required></label><label>Unit price (R)<input data-line-price type="number" min="0" step="0.01" value="${item.unitPriceCents!=null?(item.unitPriceCents/100).toFixed(2):""}" required></label><label>Discount %<input data-line-discount type="number" min="0" max="100" step="0.01" value="${item.discount||0}"></label><b data-line-total>${money(item.lineTotalCents||0)}</b><button type="button" class="danger-link" data-remove-line aria-label="Remove line">Remove</button></div>`}
function quoteDialog(id=""){
  const q=state.data.quotations.find(x=>x.id===id)||{},today=new Date().toISOString().slice(0,10),validDefault=new Date(Date.now()+30*86400000).toISOString().slice(0,10),items=q.items?.length?q.items:[{}];
  dialog(id?`Edit ${q.number}`:"Create quotation",`<div class="quote-editor"><section class="quote-fields"><div class="form-grid"><label>Client<select name="clientId" required>${clientOptions(q.client_id)}</select></label><label>Linked project<select name="projectId"><option value="">General</option>${projectOptions(q.project_id)}</select></label><label>Issue date<input name="issueDate" type="date" value="${esc(q.issue_date||today)}" required></label><label>Valid until<input name="validUntil" type="date" value="${esc(q.valid_until||validDefault)}" required></label></div><label>Quotation title / service<input name="serviceTitle" value="${esc(q.service_title||"")}" placeholder="e.g. Clinic emergency-lighting variation" required></label><label>Scope summary<textarea name="description" placeholder="Summarise the proposed work">${esc(q.description||"")}</textarea></label><div class="quote-lines-head"><h3>Line items</h3><button type="button" class="outline" data-add-line>+ Add line</button></div><div class="quote-lines" data-quote-lines>${items.map(quoteLineRow).join("")}</div><input type="hidden" name="items" data-quote-items><div class="form-grid"><label>Tax rate %<input name="taxRate" type="number" min="0" max="100" step="0.01" value="${q.tax_rate??15}" required></label><label>Deposit required (R)<input name="deposit" type="number" min="0" step="0.01" value="${q.deposit_cents?(q.deposit_cents/100).toFixed(2):"0.00"}"></label></div><label>Payment terms<textarea name="paymentTerms" placeholder="e.g. 30 days from invoice">${esc(q.payment_terms||"")}</textarea></label><label>Payment milestones<textarea name="paymentMilestones" placeholder="e.g. 30% deposit; 50% on delivery; 20% on completion">${esc(q.payment_milestones||"")}</textarea></label><label>Notes<textarea name="notes">${esc(q.notes||"")}</textarea></label></section><aside class="quote-live-preview"><span>INFINITE-X OS</span><small>${id?esc(q.number):"Number allocated on save"}</small><h3 data-preview-title>${esc(q.service_title||"New quotation")}</h3><p data-preview-client>${esc(q.client||"Select a client")}</p><dl><div><dt>Subtotal</dt><dd data-quote-subtotal>R 0.00</dd></div><div><dt>Tax</dt><dd data-quote-vat>R 0.00</dd></div><div class="total"><dt>Total</dt><dd data-quote-total>R 0.00</dd></div><div><dt>After deposit</dt><dd data-quote-balance>R 0.00</dd></div></dl><p class="basis">Totals are recalculated and validated by the business service when saved.</p></aside></div>`,data=>api(id?`/api/quotations/${id}/edit`:"/api/quotations",{method:"POST",body:JSON.stringify({...data,items:JSON.parse(data.items||"[]")})}),id?"Save revision":"Save draft");
  const form=document.querySelector("#dialog-form");form?.classList.add("quote-editor-dialog");const lines=form?.querySelector("[data-quote-lines]"),hidden=form?.querySelector("[data-quote-items]");
  const recalc=()=>{const values=[...form.querySelectorAll("[data-quote-line]")].map(row=>{const quantity=Number(row.querySelector("[data-line-quantity]").value||0),unitPrice=Number(row.querySelector("[data-line-price]").value||0),discount=Number(row.querySelector("[data-line-discount]").value||0),line=Math.round(quantity*unitPrice*100*(1-discount/100));row.querySelector("[data-line-total]").textContent=money(line);return{description:row.querySelector("[data-line-description]").value,quantity,unitPrice,discount}});hidden.value=JSON.stringify(values);const subtotal=values.reduce((sum,item)=>sum+Math.round(item.quantity*item.unitPrice*100*(1-item.discount/100)),0),tax=Number(form.elements.taxRate.value||0),vat=Math.round(subtotal*tax/100),total=subtotal+vat,deposit=Math.round(Number(form.elements.deposit.value||0)*100);form.querySelector("[data-quote-subtotal]").textContent=money(subtotal);form.querySelector("[data-quote-vat]").textContent=money(vat);form.querySelector("[data-quote-total]").textContent=money(total);form.querySelector("[data-quote-balance]").textContent=money(Math.max(0,total-deposit));form.querySelector("[data-preview-title]").textContent=form.elements.serviceTitle.value||"New quotation";form.querySelector("[data-preview-client]").textContent=form.elements.clientId.selectedOptions[0]?.textContent||"Select a client"};
  const bindLines=()=>{form.querySelectorAll("[data-quote-line] input").forEach(input=>input.oninput=recalc);form.querySelectorAll("[data-remove-line]").forEach(button=>button.onclick=()=>{if(form.querySelectorAll("[data-quote-line]").length===1)return toast("A quotation needs at least one line item.",true);button.closest("[data-quote-line]").remove();recalc()})};form.querySelector("[data-add-line]").onclick=()=>{lines.insertAdjacentHTML("beforeend",quoteLineRow());bindLines();recalc()};form.elements.taxRate.oninput=recalc;form.elements.deposit.oninput=recalc;form.elements.serviceTitle.oninput=recalc;form.elements.clientId.onchange=recalc;bindLines();recalc();
}
function paymentDialog(invoiceId){dialog("Record payment",`<label>Payment reference<input name="reference" required></label><label>Amount received (R)<input name="amount" type="number" min="0.01" step="0.01" required></label><p class="basis">Duplicate references are rejected within the active mode.</p>`,data=>api("/api/payments",{method:"POST",body:JSON.stringify({...data,invoiceId})}),"Record payment")}
function previewRecord(key){const [type,id]=key.split(":"),r=type==="quotation"?state.data.quotations.find(x=>x.id===id):state.data.invoices.find(x=>x.id===id),lines=type==="quotation"?(r.items||[]).map(item=>`<tr><td>${esc(item.description)}</td><td>${item.quantity}</td><td>${money(item.unitPriceCents)}</td><td>${item.discount||0}%</td><td>${money(item.lineTotalCents)}</td></tr>`).join(""):"";dialog(`${type==="quotation"?"Quotation":"Invoice"} preview`,`<div class="document-preview" id="printable-record"><header><div><h2>INFINITE-X OS</h2><small>AI-powered project and business management</small></div><b>${esc(r.number)}</b></header><hr><div class="document-meta"><p><b>Client</b><br>${esc(r.client)}</p>${r.issue_date?`<p><b>Issued / valid</b><br>${fmt(r.issue_date)} — ${fmt(r.valid_until)}</p>`:""}</div>${r.service_title?`<h3>${esc(r.service_title)}</h3>`:""}${r.description?`<p><b>Scope</b><br>${esc(r.description)}</p>`:""}${lines?`<div class="register-shell"><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Discount</th><th>Total</th></tr></thead><tbody>${lines}</tbody></table></div>`:""}<div class="document-totals">${r.subtotal_cents!=null?`<p>Subtotal <b>${money(r.subtotal_cents)}</b></p><p>Tax (${r.tax_rate||0}%) <b>${money(r.vat_cents)}</b></p>`:""}<p>Total <b>${money(r.total_cents)}</b></p>${r.deposit_cents?`<p>Deposit <b>${money(r.deposit_cents)}</b></p>`:""}${r.balanceCents!=null?`<p>Balance <b>${money(r.balanceCents)}</b></p>`:""}</div>${r.payment_terms?`<p><b>Payment terms</b><br>${esc(r.payment_terms)}</p>`:""}${r.payment_milestones?`<p><b>Milestones</b><br>${esc(r.payment_milestones)}</p>`:""}${r.notes?`<p><b>Notes</b><br>${esc(r.notes)}</p>`:""}<button type="button" class="outline no-print" data-print-record>Print / save as PDF</button></div>`,async()=>({}),"Close");document.querySelector("[data-print-record]")?.addEventListener("click",()=>window.print())}
function tenderDialog(){dialog("Import tender",`<label>Reference<input name="reference" required></label><label>Title<input name="title" required></label><label>Organisation<input name="organisation" required></label><label>Category<input name="category" value="Electrical" required></label><label>Description<textarea name="description" placeholder="Scope used for relevance scoring"></textarea></label><label>Close date<input name="closeDate" type="date" required></label><label>Briefing date<input name="briefingDate" type="datetime-local"></label><label>Official source link<input name="sourceUrl" type="url" placeholder="https://…" required></label><p class="basis">Relevance is calculated from the recorded title, description and category. It does not determine eligibility.</p>`,data=>api("/api/tenders",{method:"POST",body:JSON.stringify(data)}),"Import tender")}
function requirementDialog(tenderId){dialog("Add tender requirement",`<label>Requirement<input name="label" required></label><label>Status<select name="status"><option>Missing</option><option>Provided</option><option>Verified</option></select></label><label>Document reference<input name="documentRef"></label><label class="confirm"><input name="mandatory" type="checkbox" checked> Mandatory for submission</label>`,data=>api("/api/tender-requirements",{method:"POST",body:JSON.stringify({...data,tenderId,mandatory:data.mandatory==="on"})}),"Add requirement")}
