function fundingDialog(){dialog("New funding need",`<label>Type<select name="type"><option>PO funding</option><option>Project working capital</option><option>Invoice finance</option><option>Operational funding</option></select></label><label>Purpose<textarea name="purpose" required></textarea></label><label>Linked project<select name="projectId"><option value="">None</option>${projectOptions()}</select></label><label>Linked invoice<select name="invoiceId"><option value="">None</option>${state.data.invoices.map(x=>`<option value="${x.id}">${esc(x.number)}</option>`).join("")}</select></label><label>PO reference<input name="poReference"></label><label>Provider<input name="provider" placeholder="Not selected"></label><label>Required cost (R)<input name="required" type="number" min="0" step="0.01" required></label><label>Confirmed available funds (R)<input name="available" type="number" min="0" step="0.01" value="0" required></label><label>Recorded repayment terms<textarea name="terms"></textarea></label>`,data=>api("/api/funding",{method:"POST",body:JSON.stringify(data)}),"Create need")}
