function expenseDialog(){dialog("Record expense",`<label>Description<input name="description" required></label><label>Project<select name="projectId"><option value="">General operations</option>${projectOptions()}</select></label><label>Amount (R)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Incurred date<input name="incurredAt" type="date" value="${new Date().toISOString().slice(0,10)}" required></label>`,data=>api("/api/expenses",{method:"POST",body:JSON.stringify(data)}),"Record expense")}
function complianceDialog(id=""){const c=state.data.compliance.find(x=>x.id===id)||{};dialog(id?"Update compliance requirement":"New compliance requirement",`<div class="form-grid"><label>Category<select name="category">${["Company","Tax","Employment","Tendering","Construction","Electrical","Health & safety","Insurance","Information governance","Skills","Operations","Records","Other"].map(x=>`<option ${x===(c.category||"Other")?"selected":""}>${x}</option>`).join("")}</select></label><label>Responsible authority<input name="authority" value="${esc(c.authority||"")}" placeholder="e.g. SARS"></label></div><label>Requirement title<input name="title" value="${esc(c.title||"")}" required></label><label>Standard / reference<input name="standardRef" value="${esc(c.standard_ref||"")}"></label><label>Applicability<input name="applicability" value="${esc(c.applicability||"Confirm applicability")}" required></label><label>Review / filing frequency<input name="frequency" value="${esc(c.frequency||"")}" placeholder="Annual, monthly, per project…"></label><div class="form-grid"><label>Owner<select name="ownerId">${userOptions(c.owner_id)}</select></label><label>Expiry / review date<input name="expiryDate" type="date" value="${esc(c.expiry_date||"")}"></label></div><label>Status<select name="status">${["Review applicability","Evidence required","Under review","Expiring soon","Compliant","Non-compliant","Not applicable"].map(x=>`<option ${x===c.status?"selected":""}>${x}</option>`).join("")}</select></label><label>Evidence reference<input name="evidence" value="${esc(c.evidence||"")}"></label><label class="confirm"><input name="mandatory" type="checkbox" ${c.mandatory?"checked":""}> Required for this company or engagement</label><div class="form-grid"><label>Linked record type<input name="relatedType" value="${esc(c.related_type||"company")}" placeholder="project, tender, company"></label><label>Linked record ID<input name="relatedId" value="${esc(c.related_id||"")}"></label></div><label>Notes<textarea name="notes">${esc(c.notes||"")}</textarea></label><p class="basis">Baseline entries require an applicability review; changing status records the operational assessment, not legal certification.</p>`,data=>api(id?`/api/compliance/${id}/edit`:"/api/compliance",{method:"POST",body:JSON.stringify({...data,mandatory:data.mandatory==="on"})}),id?"Save requirement":"Create requirement")}
function documentDialog(){dialog("Upload document",`<label>Document title<input name="title" required></label><label>Related record type<select name="relatedType"><option>project</option><option>task</option><option>tender</option><option>funding</option><option>compliance</option><option>invoice</option><option>general</option></select></label><label>Related record ID<input name="relatedId"></label><label>File<input name="file" type="file" required></label><p class="basis">Maximum 1 MB. Uploading the same title creates a new revision and supersedes the prior current revision.</p>`,async data=>{const input=document.querySelector('#dialog-form input[type="file"]'),file=input.files[0];if(!file)throw new Error("Choose a file.");if(file.size>1_000_000)throw new Error("File exceeds the 1 MB limit.");const contentBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]);reader.onerror=()=>reject(new Error("Unable to read file."));reader.readAsDataURL(file)});return api("/api/documents",{method:"POST",body:JSON.stringify({...data,file:undefined,fileName:file.name,mimeType:file.type||"application/octet-stream",contentBase64})})},"Upload document")}
